const COUNTRY_IDS = Object.keys(COUNTRIES);
// Current display country. App sets this on every render before its children render.
let CUR = COUNTRIES.PK;
const MODEL_INDEX = COUNTRY_IDS.flatMap((cc) => COUNTRIES[cc].catalog.map((m) => ({ ...m, country: cc })));
const findModel = (name) => {
  const n = String(name || "").toLowerCase();
  return MODEL_INDEX.find((m) => n === m.name.toLowerCase()) || MODEL_INDEX.find((m) => n.includes(m.name.toLowerCase()) || m.name.toLowerCase().includes(n) && n.length > 6) || null;
};
// Model-specific photo files: public/machines/<slug>.jpg. Distinct tractor models never share a slug,
// and a missing file falls back to the bundled photo for the machine's own category (never another category's).
const machineSlug = (category, name) => {
  const n = String(name || "").toLowerCase();
  let m;
  if ((m = n.match(/\b(?:massey|mf|millat)\b[^0-9]*(\d{3})\b/))) return "mf-" + m[1];
  if (/ghazi/.test(n)) return "ghazi-" + ((n.match(/(\d{2,3})\s*hp/) || [])[1] || "65") + "hp";
  if ((m = n.match(/\bfiat\b[^0-9]*(\d{3})\b/))) return "fiat-" + m[1];
  if (/dabung/.test(n)) return "nh-dabung-85";
  if (category === "harvester" || /combine|harvester/.test(n)) return "combine-harvester";
  if (category === "leveler" || /level/.test(n)) return "laser-land-leveler";
  if (category === "thresher" || /thresher|sheller/.test(n)) return "thresher";
  const slug = n.replace(/[^a-z0-9]+/g, "-").replace(/^-|-$/g, "");
  return slug || null;
};
const MACHINE_FILE_MISSING = new Set(); // slugs whose local file failed once; skip them for the rest of the visit
const photoKeyFor = (category, name) => {
  const m = name ? findModel(name) : null;
  if (m && m.cat === category && m.photo !== undefined) return m.photo;
  return CAT_PHOTO[category] || null;
};
const catalogCats = (cc) => [...new Set(COUNTRIES[cc].catalog.map((m) => m.cat))];
// Typical owner ask for a category in the current country, in PKR (catalog mid-point)
const askFor = (category, fallback) => {
  const ms = CUR.catalog.filter((m) => m.cat === category);
  if (!ms.length) return fallback;
  const mid = ms.reduce((s, m) => s + (m.min + m.max) / 2, 0) / ms.length;
  return mid / CUR.fx;
};
const toLocal = (pkrV) => Math.round(Number(pkrV || 0) * CUR.fx * 100) / 100;
const fromLocal = (v) => Number(v || 0) / CUR.fx;
const fmtLocal = (v, cur = CUR) => {
  const abs = Math.abs(v);
  const dec = cur.id === "PK" || cur.code === "INR" || abs === 0 ? 0 : abs >= 10 ? 0 : cur.code === "USD" ? 2 : 1;
  return cur.symbol + Number(v).toLocaleString(cur.locale === "zh-CN" ? "en-US" : cur.locale, { minimumFractionDigits: dec, maximumFractionDigits: dec });
};
// transport tariffs in PKR for the current country
// Pakistan tariffs follow the live diesel price: 100 PKR/km, 500 PKR minimum and 60 PKR/km long haul were set
// at the 360 PKR/L benchmark, and move with diesel (kept between 70% and 150% of that)
const fuelFactor = () => (CUR.id === "PK" ? Math.min(1.5, Math.max(0.7, LIVE_DIESEL / DIESEL_BENCHMARK)) : 1);
const trKm = () => (CUR.id === "PK" ? Math.round(TRANSPORT_PER_KM * fuelFactor()) : CUR.transportKm / CUR.fx);
const trMin = () => (CUR.id === "PK" ? Math.round((TRANSPORT_MIN * fuelFactor()) / 50) * 50 : CUR.transportMin / CUR.fx);
const trLong = () => (CUR.id === "PK" ? Math.round(LONG_TRANSPORT_PER_KM * fuelFactor()) : CUR.longKm / CUR.fx);

