/* ------------------------------------------------------------------ */
/* Digital booking voucher (printable, downloadable)                   */
/* ------------------------------------------------------------------ */
const voucherCode = (b) => {
  const digits = String(b.id || "").replace(/\D/g, "").slice(-3).padStart(3, "0");
  const yr = new Date(b.createdAt || Date.now()).getFullYear();
  return `#AS-${yr}-${digits}`;
};
// Deterministic QR-style pattern (decorative verification badge, not a scannable QR code)
function VerifyPattern({ seed, size = 116 }) {
  const n = 21;
  const rnd = seededRandom(String(seed));
  const finder = (r, c) => (r < 7 && c < 7) || (r < 7 && c >= n - 7) || (r >= n - 7 && c < 7);
  const cells = [];
  for (let r = 0; r < n; r++) for (let c = 0; c < n; c++) if (!finder(r, c) && rnd() > 0.52) cells.push([r, c]);
  const Finder = ({ x, y }) => (<g><rect x={x} y={y} width="7" height="7" fill="#145A32" /><rect x={x + 1} y={y + 1} width="5" height="5" fill="#fff" /><rect x={x + 2} y={y + 2} width="3" height="3" fill="#145A32" /></g>);
  return (
    <svg viewBox={`-1 -1 ${n + 2} ${n + 2}`} width={size} height={size} role="img" aria-label="Verification pattern" shapeRendering="crispEdges">
      <rect x="-1" y="-1" width={n + 2} height={n + 2} fill="#fff" />
      {cells.map(([r, c]) => <rect key={r + "-" + c} x={c} y={r} width="1" height="1" fill="#145A32" />)}
      <Finder x={0} y={0} /><Finder x={n - 7} y={0} /><Finder x={0} y={n - 7} />
    </svg>
  );
}

/* ------------------------------------------------------------------ */
/* Split bill, official collection account, commission receipts and    */
/* photo / video work proofs. App provides the data through DealsCtx,   */
/* so bills and deal cards can show them without extra props.          */
/* ------------------------------------------------------------------ */
const DealsCtx = React.createContext(null);
const useDeals = () => React.useContext(DealsCtx);
const PROOF_STAGES = ["before", "after", "meter", "land"];
const PROOF_VIDEO_MAX = 650 * 1024; // short clips only: a Firestore document holds at most 1 MiB
const dealKeyOf = (deal) => `${deal.kind}_${deal.id}`;
const bookingDeal = (b) => ({ kind: "booking", id: b.id, title: b.listingName, amount: b.walletPaid ? 0 : Math.round((b.quote && b.quote.commission) || 0), uids: [b.renterUid, b.ownerUid].filter(Boolean), farmerUid: b.renterUid || "", ownerUid: b.ownerUid || "" });
const landDeal = (b) => ({ kind: "land", id: b.id, title: uniqPlaces(b.village, b.district) || b.id, amount: b.walletPaid ? 0 : landCommFor(b).amount, uids: [b.tenantUid, b.ownerUid].filter(Boolean), farmerUid: b.tenantUid || "", ownerUid: b.ownerUid || "" });
const isDealParty = (ctx, deal) => !!(ctx && ctx.session && ctx.session.uid && deal && !deal.sample && (ctx.isFounder || deal.uids.includes(ctx.session.uid)));
const readFileAsDataUrl = (file) => new Promise((resolve, reject) => {
  const r = new FileReader();
  r.onload = () => resolve(String(r.result || ""));
  r.onerror = () => reject(new Error("unreadable file"));
  r.readAsDataURL(file);
});

// Launch offer: free-commission deals left per category for the signed-in owner / seller
function PromoPill({ t, used, className = "" }) {
  if (!used) return null;
  const items = [["machinery", "promo_cat_machinery"], ["crop", "promo_cat_crop"], ["land", "promo_cat_land"]].map(([k, label]) => {
    const of = PROMO_FREE[k], left = Math.max(0, of - (used[k] || 0));
    return { k, label: t(label), left, of };
  });
  const any = items.some((x) => x.left > 0);
  return (
    <div className={`rounded-2xl bg-gradient-to-r from-leaf/15 via-gold/10 to-leaf/10 p-3 ring-1 ring-leaf/30 ${className}`} role="status">
      <p className="flex flex-wrap items-center gap-2 text-sm font-extrabold text-forest rtl:leading-[2]">
        <span className="flex h-7 w-7 items-center justify-center rounded-full bg-forest text-gold"><Gift className="h-4 w-4" aria-hidden="true" /></span>
        {t("promo_title")}
      </p>
      <ul className="mt-2 flex flex-wrap gap-1.5">
        {items.map((x) => (
          <li key={x.k} className={`inline-flex items-center gap-1.5 rounded-full px-2.5 py-1 text-xs font-bold ring-1 rtl:leading-[2] ${x.left > 0 ? "bg-white text-forest ring-leaf/40" : "bg-soil/5 text-soil/70 ring-soil/15"}`}>
            {x.label}: <span dir="ltr" className="tabular-nums">{x.left}/{x.of}</span> {t("promo_free_word")}
          </li>
        ))}
      </ul>
      <p className="mt-1.5 text-[11px] leading-snug text-soil/80 rtl:leading-[2]">{t(any ? "promo_note" : "promo_used_up")}</p>
    </div>
  );
}

/* ------------------------------------------------------------------ */
/* Prepaid Agri-Wallet (agri_wallets/{uid}): the member tops up through */
/* the official collection account; the founder checks the receipt and  */
/* credits it; commission on confirmed deals is taken from it.          */
/* ------------------------------------------------------------------ */
const TOPUP_PRESETS = [500, 1000, 2500, 5000, 10000];
const TOPUP_MIN = 100, TOPUP_MAX = 1000000;
const walletTxLabel = (t, x) => t({ topup: "aw_tx_topup", booking: "aw_tx_booking", land: "aw_tx_land", crop: "aw_tx_crop" }[x.kind] || "aw_tx_other");
const topupTone = { pending: "bg-gold/20 text-soil ring-gold/40", credited: "bg-leaf/15 text-forest ring-leaf/30", rejected: "bg-red-50 text-red-700 ring-red-200" };

function AgriWalletCard({ t, wallet, topups = [], need = 0, onTopUp, className = "", ...rest }) {
  const bal = wallet ? Math.round(Number(wallet.balance) || 0) : 0;
  const txns = (wallet && Array.isArray(wallet.txns) ? wallet.txns : []).slice(0, 12);
  const pending = topups.filter((x) => x.status === "pending").sort((a, b) => (b.createdAt || 0) - (a.createdAt || 0));
  const recent = topups.filter((x) => x.status !== "pending").sort((a, b) => (b.createdAt || 0) - (a.createdAt || 0)).slice(0, 3);
  const low = need > 0 && bal < need;
  return (
    <div className={`grid scroll-mt-24 gap-4 lg:grid-cols-[1fr_1.2fr] ${className}`} {...rest}>
      <div className="relative overflow-hidden rounded-2xl bg-[linear-gradient(150deg,#14532d,#0f3d23_55%,#052e16)] p-5 text-ivory shadow-md">
        <span className="pointer-events-none absolute inset-0 bg-[linear-gradient(115deg,transparent_35%,rgba(255,255,255,0.12)_48%,transparent_60%)]" aria-hidden="true" />
        <p className="relative flex items-center gap-2 text-sm font-bold text-gold rtl:leading-[2]"><Wallet className="h-4 w-4" aria-hidden="true" />{t("aw_balance")}</p>
        <p className="relative mt-2 font-display text-3xl font-extrabold tabular-nums" dir="ltr">{pkr(bal)}</p>
        <p className="relative mt-2 text-xs leading-snug text-ivory/80 rtl:leading-[2]">{t("aw_sub")}</p>
        {low && <p className="relative mt-3 rounded-xl bg-red-600/90 p-2.5 text-xs font-bold text-white rtl:leading-[2]" role="alert">{t("aw_low")} · {t("aw_low_need").replace("{need}", pkr(need)).replace("{bal}", pkr(bal))}</p>}
        <button type="button" onClick={onTopUp} className="relative mt-4 inline-flex min-h-[44px] items-center gap-2 rounded-xl bg-gold px-4 text-sm font-extrabold text-soil shadow transition hover:brightness-105"><Plus className="h-4 w-4" aria-hidden="true" />{t("aw_topup")}</button>
      </div>
      <div className="rounded-2xl border border-soil/10 bg-white p-4 shadow-sm">
        <h3 className="flex items-center gap-2 font-bold text-forest rtl:leading-[2]"><Banknote className="h-4 w-4 text-gold" aria-hidden="true" />{t("aw_ledger")}</h3>
        {pending.length > 0 && (
          <ul className="mt-2 space-y-1.5">
            {pending.map((x) => (
              <li key={x.id} className="flex flex-wrap items-center justify-between gap-2 rounded-lg bg-gold/10 px-3 py-2 text-xs ring-1 ring-gold/30">
                <span className="font-semibold text-soil rtl:leading-[2]">{t("aw_tx_topup_req")} · <span dir="ltr">{fmtStamp(x.createdAt)}</span></span>
                <span className="flex items-center gap-2"><b className="tabular-nums" dir="ltr">+{pkr(x.amount)}</b><span className={`rounded-full px-2 py-0.5 font-bold ring-1 ${topupTone.pending}`}>{t("aw_st_pending")}</span></span>
              </li>
            ))}
          </ul>
        )}
        {txns.length === 0 && pending.length === 0 ? <p className="mt-2 rounded-xl bg-ivory p-4 text-sm text-soil/80">{t("aw_none")}</p> : (
          <ul className="mt-2 divide-y divide-soil/10">
            {txns.map((x, i) => (
              <li key={(x.id || "") + i} className="flex items-center justify-between gap-3 py-2 text-sm">
                <span className="min-w-0">
                  <span className="block font-semibold text-soil rtl:leading-[2]">{walletTxLabel(t, x)}</span>
                  <span className="block truncate text-[11px] text-soil/70" dir="ltr">{[x.note, fmtStamp(x.at)].filter(Boolean).join(" · ")}</span>
                </span>
                <b className={`shrink-0 tabular-nums ${x.amount >= 0 ? "text-forest" : "text-red-800"}`} dir="ltr">{x.amount >= 0 ? "+" : "−"}{pkr(Math.abs(x.amount || 0))}</b>
              </li>
            ))}
          </ul>
        )}
        {recent.filter((x) => x.status === "rejected").map((x) => (
          <p key={x.id} className={`mt-2 rounded-lg px-3 py-2 text-xs font-semibold ring-1 ${topupTone.rejected}`}>{t("aw_tx_topup_req")} <span dir="ltr">{pkr(x.amount)}</span> · {t("aw_st_rejected")}</p>
        ))}
      </div>
    </div>
  );
}

function TopUpModal({ t, session, toast, onClose }) {
  const [amount, setAmount] = useState(1000);
  const [custom, setCustom] = useState("");
  const [txnId, setTxnId] = useState("");
  const [receipt, setReceipt] = useState("");
  const [busy, setBusy] = useState(false);
  const [err, setErr] = useState("");
  const amt = custom ? Math.round(Number(custom) || 0) : amount;
  const pickFile = async (e) => {
    const file = e.target.files && e.target.files[0]; e.target.value = "";
    if (!file) return;
    try { setReceipt(await shrinkPhoto(file)); setErr(""); } catch (x) { setErr(t("aw_tu_err_photo")); }
  };
  const submit = async (e) => {
    e.preventDefault();
    if (!(amt >= TOPUP_MIN && amt <= TOPUP_MAX)) { setErr(t("aw_tu_err_amount")); return; }
    if (!receipt && !txnId.trim()) { setErr(t("aw_tu_err_receipt")); return; }
    setBusy(true); setErr("");
    const id = "TU-" + Date.now().toString(36).toUpperCase() + "-" + Math.random().toString(36).slice(2, 6).toUpperCase();
    try {
      await writeDoc(COL.walletTopups, id, { uid: session.uid, name: String(session.name || "").slice(0, 80), email: session.email || "", phone: session.phone || "", amount: amt, txnId: txnId.trim().slice(0, 60), receipt: receipt || "", status: "pending", createdAt: Date.now() });
      toast(t("aw_tu_sent"), { title: t("aw_tu_title") });
      onClose();
    } catch (x) { setErr(t("aw_tu_err")); setBusy(false); }
  };
  return (
    <SheetModal title={t("aw_tu_title")} onClose={onClose} labelledBy="aw-tu-h">
      <form onSubmit={submit} noValidate className="space-y-4">
        <div>
          <p className="mb-1.5 text-sm font-bold text-forest rtl:leading-[2]">{t("aw_tu_step1")}</p>
          <CompanyAccountCard t={t} deal={null} />
        </div>
        <fieldset>
          <legend className="mb-1.5 text-sm font-bold text-forest rtl:leading-[2]">{t("aw_tu_amount")}</legend>
          <div className="grid grid-cols-3 gap-2 sm:grid-cols-5">
            {TOPUP_PRESETS.map((v) => (
              <button key={v} type="button" onClick={() => { setAmount(v); setCustom(""); }} aria-pressed={!custom && amount === v}
                className={`min-h-[44px] rounded-xl text-sm font-bold ring-1 tabular-nums ${!custom && amount === v ? "bg-forest text-ivory ring-forest" : "bg-ivory text-soil ring-soil/15"}`} dir="ltr">{pkr(v)}</button>
            ))}
          </div>
          <label htmlFor="aw-custom" className="mt-2 block text-xs font-semibold text-soil/80">{t("aw_tu_custom")}</label>
          <input id="aw-custom" type="number" inputMode="numeric" min={TOPUP_MIN} max={TOPUP_MAX} value={custom} onChange={(e) => setCustom(e.target.value)} className={`${inputCls} mt-1`} dir="ltr" />
        </fieldset>
        <div>
          <label htmlFor="aw-txn" className="mb-1 block text-sm font-bold text-forest rtl:leading-[2]">{t("aw_tu_txn")}</label>
          <input id="aw-txn" type="text" maxLength={60} value={txnId} onChange={(e) => setTxnId(e.target.value)} className={inputCls} dir="ltr" />
        </div>
        <div>
          <p className="mb-1 text-sm font-bold text-forest rtl:leading-[2]">{t("aw_tu_receipt")}</p>
          {receipt ? (
            <div className="flex items-center gap-3"><img src={receipt} alt={t("aw_tu_receipt")} className="h-20 w-20 rounded-lg object-cover ring-1 ring-soil/15" /><button type="button" onClick={() => setReceipt("")} className="rounded-lg border border-soil/20 px-3 py-2 text-xs font-bold text-soil">{t("aw_tu_remove")}</button></div>
          ) : (
            <label className="flex min-h-[48px] cursor-pointer items-center justify-center gap-2 rounded-xl border-2 border-dashed border-forest/30 bg-ivory px-3 text-sm font-bold text-forest"><Camera className="h-4 w-4" aria-hidden="true" />{t("aw_tu_add_photo")}<input type="file" accept="image/*" className="sr-only" onChange={pickFile} /></label>
          )}
        </div>
        {err && <p className="rounded-lg bg-red-50 p-2.5 text-sm font-semibold text-red-800 ring-1 ring-red-200 rtl:leading-[2]" role="alert">{err}</p>}
        <button type="submit" disabled={busy} className="inline-flex min-h-[48px] w-full items-center justify-center gap-2 rounded-xl bg-forest px-4 text-sm font-extrabold text-ivory disabled:opacity-60">{busy ? <Hourglass className="h-4 w-4 animate-pulse" aria-hidden="true" /> : <Upload className="h-4 w-4" aria-hidden="true" />}{t("aw_tu_submit")} · <span dir="ltr">{pkr(amt || 0)}</span></button>
        <p className="text-[11px] leading-snug text-soil/80 rtl:leading-[2]">{t("aw_tu_note")}</p>
      </form>
    </SheetModal>
  );
}

// Founder: check each top-up receipt, then credit the member's wallet with one click
function WalletTopupsAdmin({ t, toast, isFounder }) {
  const [list, setList] = useState(null);
  const [busy, setBusy] = useState("");
  const [view, setView] = useState(null); // receipt being viewed
  useEffect(() => (isFounder ? watchCollection(COL.walletTopups, (l) => setList(l), () => setList([])) : undefined), [isFounder]);
  if (!isFounder) return <p className="rounded-xl bg-ivory p-6 text-center text-sm text-soil/80">{t("adw_founder_only")}</p>;
  const rows = (list || []).slice().sort((a, b) => (a.status === "pending" ? 0 : 1) - (b.status === "pending" ? 0 : 1) || (b.createdAt || 0) - (a.createdAt || 0));
  const credit = async (x) => {
    if (busy || x.status !== "pending") return;
    setBusy(x.id);
    try {
      try { await walletApply(x.uid, Math.round(Number(x.amount) || 0), { id: "topup_" + x.id, kind: "topup", ref: x.id, note: x.txnId || x.id }); }
      catch (e) { if (!e || e.code !== "duplicate") throw e; } // already credited earlier: just close the request
      await writeDoc(COL.walletTopups, x.id, { ...x, status: "credited", decidedAt: Date.now() });
      toast(t("adw_done").replace("{amt}", pkr(x.amount)).replace("{name}", x.name || "·"));
    } catch (e) { toast(t("adw_err"), { type: "error" }); }
    setBusy("");
  };
  const reject = async (x) => {
    if (busy) return;
    setBusy(x.id);
    try { await writeDoc(COL.walletTopups, x.id, { ...x, status: "rejected", decidedAt: Date.now() }); toast(t("adw_rejected")); }
    catch (e) { toast(t("adw_err"), { type: "error" }); }
    setBusy("");
  };
  return (
    <div className="rounded-2xl border border-soil/10 bg-white p-4 shadow-sm">
      <h3 className="flex items-center gap-2 font-bold text-forest rtl:leading-[2]"><Wallet className="h-4 w-4 text-gold" aria-hidden="true" />{t("adw_title")}</h3>
      <p className="mt-1 text-xs text-soil/80 rtl:leading-[2]">{t("adw_sub")}</p>
      {list === null ? <p className="mt-3 text-sm text-soil/80"><Hourglass className="me-1 inline h-4 w-4 animate-pulse" aria-hidden="true" /></p>
        : rows.length === 0 ? <p className="mt-3 rounded-xl bg-ivory p-6 text-center text-sm text-soil/80">{t("adw_none")}</p> : (
        <ul className="mt-3 grid gap-3 md:grid-cols-2">
          {rows.map((x) => (
            <li key={x.id} className={`rounded-xl p-3 ring-1 ${x.status === "pending" ? "bg-gold/5 ring-gold/40" : "bg-ivory/60 ring-soil/10"}`}>
              <div className="flex items-start gap-3">
                {x.receipt ? <button type="button" onClick={() => setView(x)} className="shrink-0" aria-label={t("aw_tu_receipt")}><img src={x.receipt} alt="" className="h-16 w-16 rounded-lg object-cover ring-1 ring-soil/15" /></button>
                  : <span className="flex h-16 w-16 shrink-0 items-center justify-center rounded-lg bg-white text-soil/50 ring-1 ring-soil/15"><Banknote className="h-6 w-6" aria-hidden="true" /></span>}
                <div className="min-w-0 flex-1 text-sm">
                  <p className="flex flex-wrap items-center justify-between gap-2"><b className="break-words text-forest">{x.name || "·"}</b><span className={`rounded-full px-2 py-0.5 text-[11px] font-bold ring-1 ${topupTone[x.status] || ""}`}>{t("aw_st_" + (x.status || "pending"))}</span></p>
                  <p className="font-display text-lg font-extrabold text-forest tabular-nums" dir="ltr">{pkr(x.amount)}</p>
                  <p className="break-all text-xs text-soil/80" dir="ltr">{t("adw_txn")}: {x.txnId || "·"} · {fmtStamp(x.createdAt)}</p>
                  {(x.phone || x.email) && <p className="break-all text-xs text-soil/80" dir="ltr">{[x.phone, x.email].filter(Boolean).join(" · ")}</p>}
                </div>
              </div>
              {x.status === "pending" && (
                <div className="mt-3 flex gap-2">
                  <button type="button" disabled={!!busy} onClick={() => credit(x)} className="inline-flex min-h-[44px] flex-1 items-center justify-center gap-1.5 rounded-lg bg-forest px-3 text-sm font-bold text-ivory disabled:opacity-60">{busy === x.id ? <Hourglass className="h-4 w-4 animate-pulse" aria-hidden="true" /> : <BadgeCheck className="h-4 w-4" aria-hidden="true" />}{t("adw_approve")}</button>
                  <button type="button" disabled={!!busy} onClick={() => reject(x)} className="min-h-[44px] rounded-lg border border-red-300 px-3 text-sm font-bold text-red-800 disabled:opacity-60">{t("adw_reject")}</button>
                </div>
              )}
            </li>
          ))}
        </ul>
      )}
      {view && (
        <SheetModal title={`${t("aw_tu_receipt")} · ${view.name || ""}`} onClose={() => setView(null)} labelledBy="adw-rc-h">
          <img src={view.receipt} alt={t("aw_tu_receipt")} className="w-full rounded-xl object-contain ring-1 ring-soil/15" />
        </SheetModal>
      )}
    </div>
  );
}

// Two clear lines: what goes to PakAgriShare, what goes to the owner. They always add up to the bill total.
function CommissionSplit({ t, commission, total, promo = null, className = "" }) {
  const c = Math.max(0, Math.round(Number(commission) || 0));
  const net = Math.max(0, Math.round(Number(total) || 0) - c);
  const line = (Icon, tone, title, sub, value) => (
    <div className="flex items-start gap-3 p-3">
      <span className={`flex h-9 w-9 shrink-0 items-center justify-center rounded-xl ${tone}`}><Icon className="h-4 w-4" aria-hidden="true" /></span>
      <div className="min-w-0 flex-1">
        <p className="text-sm font-extrabold text-forest rtl:leading-[2]">{title}</p>
        <p className="text-[11px] leading-snug text-soil/80 rtl:leading-[2]">{sub}</p>
      </div>
      <p className="shrink-0 font-display text-base font-extrabold text-forest tabular-nums" dir="ltr">{pkr(value)}</p>
    </div>
  );
  return (
    <div className={`divide-y divide-soil/10 overflow-hidden rounded-xl bg-white ring-1 ring-soil/15 ${className}`}>
      {line(Landmark, promo ? "bg-leaf/20 text-forest" : "bg-gold/20 text-soil", promo ? `${t("cs_comm_t")} · 0%` : t("cs_comm_t"), promo ? promoText(t, promo) : t("cs_comm_s"), c)}
      {line(HandCoins, "bg-leaf/15 text-forest", t("cs_net_t"), promo ? t("promo_net_s") : t("cs_net_s"), net)}
    </div>
  );
}

// PakAgriShare official collection account (app_settings/company_payment) plus the receipt upload for this deal
function CompanyAccountCard({ t, deal, className = "" }) {
  const ctx = useDeals();
  const cp = (ctx && ctx.company) || {};
  const rows = [["ca_bank", cp.bankName], ["ca_acc_title", cp.accountTitle], ["ca_iban", cp.iban], ["ca_jazz", cp.jazzcash], ["ca_easy", cp.easypaisa], ["ca_raast", cp.raast]].filter((r) => r[1]);
  return (
    <div className={`rounded-xl bg-forest/[0.04] p-3 ring-1 ring-forest/15 ${className}`}>
      <p className="flex items-center gap-2 text-sm font-extrabold text-forest rtl:leading-[2]"><Landmark className="h-4 w-4 text-gold" aria-hidden="true" />{t("ca_title")}</p>
      <p className="mt-0.5 text-[11px] leading-snug text-soil/80 rtl:leading-[2]">{t("ca_sub")}</p>
      {rows.length ? (
        <dl className="mt-2 divide-y divide-soil/10 rounded-lg bg-white px-3 text-sm ring-1 ring-soil/10">
          {rows.map(([k, v]) => (
            <div key={k} className="flex flex-wrap items-baseline justify-between gap-x-3 gap-y-0.5 py-1.5">
              <dt className="text-xs text-soil/80">{t(k)}</dt>
              <dd className="min-w-0 break-all text-end font-mono text-[13px] font-bold text-soil" dir="ltr">{v}</dd>
            </div>
          ))}
        </dl>
      ) : (
        <p className="mt-2 rounded-lg bg-white p-2.5 text-xs text-soil ring-1 ring-soil/10 rtl:leading-[2]">{t("ca_none")} <a href={`tel:${CONSULTANT.primary.tel}`} className="font-bold text-forest underline" dir="ltr">{CONSULTANT.primary.label}</a></p>
      )}
      {deal && deal.amount > 0 && <div className="no-print mt-3"><ReceiptButton t={t} deal={deal} /></div>}
    </div>
  );
}

function ReceiptButton({ t, deal }) {
  const ctx = useDeals();
  const [open, setOpen] = useState(false);
  if (!isDealParty(ctx, deal)) return null;
  const r = ctx.receipts[dealKeyOf(deal)];
  return (
    <div className="flex flex-wrap items-center gap-2">
      {r && r.status === "verified" ? (
        <span className="inline-flex items-center gap-1.5 rounded-full bg-leaf/15 px-3 py-1.5 text-xs font-bold text-forest ring-1 ring-leaf/30"><BadgeCheck className="h-4 w-4" aria-hidden="true" />{t("rc_verified")}</span>
      ) : (
        <>
          {r && <span className="inline-flex items-center gap-1.5 rounded-full bg-gold/20 px-3 py-1.5 text-xs font-bold text-soil ring-1 ring-gold/40"><Hourglass className="h-3.5 w-3.5" aria-hidden="true" />{t("rc_pending")}</span>}
          <button type="button" onClick={() => setOpen(true)} className="inline-flex min-h-[44px] items-center gap-2 rounded-xl bg-forest px-3.5 text-sm font-bold text-ivory"><Upload className="h-4 w-4" aria-hidden="true" />{t(r ? "rc_replace" : "rc_upload")}</button>
        </>
      )}
      {open && <ReceiptModal t={t} deal={deal} onClose={() => setOpen(false)} />}
    </div>
  );
}

function SheetModal({ title, onClose, children, labelledBy }) {
  useEffect(() => {
    const k = (e) => { if (e.key === "Escape") onClose(); };
    window.addEventListener("keydown", k);
    return () => window.removeEventListener("keydown", k);
  }, [onClose]);
  return createPortal(
    <div className="fixed inset-0 z-[95] flex items-end justify-center bg-soil/50 backdrop-blur-sm sm:items-center sm:p-4" onClick={onClose}>
      <div className="sheet-in max-h-[92vh] w-full max-w-md overflow-y-auto rounded-t-3xl bg-white p-5 pb-24 shadow-2xl sm:rounded-3xl sm:pb-5" onClick={(e) => e.stopPropagation()} role="dialog" aria-modal="true" aria-labelledby={labelledBy}>
        <div className="mb-4 flex items-start justify-between gap-3">
          <h3 id={labelledBy} className="font-display text-lg font-extrabold text-forest rtl:leading-[2]">{title}</h3>
          <button type="button" onClick={onClose} aria-label="Close" className="flex h-10 w-10 shrink-0 items-center justify-center rounded-xl text-soil ring-1 ring-soil/15 hover:bg-ivory"><X className="h-5 w-5" aria-hidden="true" /></button>
        </div>
        {children}
      </div>
    </div>,
    document.body
  );
}

function ReceiptModal({ t, deal, onClose }) {
  const ctx = useDeals();
  const prev = ctx.receipts[dealKeyOf(deal)];
  const [amount, setAmount] = useState(prev ? prev.amount : deal.amount);
  const [ref, setRef] = useState(prev ? prev.ref || "" : "");
  const [photo, setPhoto] = useState("");
  const [err, setErr] = useState("");
  const [busy, setBusy] = useState(false);
  const pick = (e) => {
    const file = e.target.files && e.target.files[0];
    e.target.value = "";
    if (!file) return;
    setErr("");
    shrinkPhoto(file).then(setPhoto).catch(() => setErr(t("ow_photo_err")));
  };
  const submit = (e) => {
    e.preventDefault();
    if (!photo) { setErr(t("rc_need_photo")); return; }
    if (!isDealParty(ctx, deal)) { setErr(t("rc_not_party")); return; }
    setBusy(true);
    const now = Date.now();
    const doc = {
      dealKey: dealKeyOf(deal), kind: deal.kind, dealId: deal.id, amount: Math.max(0, Math.round(Number(amount) || 0)), photo, ref: String(ref || "").slice(0, 100),
      uids: deal.uids, ownerUid: deal.ownerUid || "", byUid: ctx.session.uid, byName: ctx.session.name || "", status: "pending", createdAt: prev ? prev.createdAt || now : now, updatedAt: now,
    };
    ctx.saveReceipt(doc).then(() => { ctx.toast(t("rc_sent")); onClose(); }).catch(() => { setBusy(false); setErr(t("rc_err")); });
  };
  return (
    <SheetModal title={t("rc_title")} onClose={onClose} labelledBy="rc-h">
      <form onSubmit={submit} noValidate className="space-y-4">
        <p className="rounded-xl bg-ivory px-3 py-2 text-xs text-soil" dir="auto"><span dir="ltr" className="font-mono font-bold">{deal.id}</span> · {deal.title}</p>
        <Field label={t("rc_amount")} htmlFor="rc-amt"><input id="rc-amt" type="number" inputMode="numeric" min="0" dir="ltr" value={amount} onChange={(e) => setAmount(e.target.value)} className={inputCls + " text-lg font-extrabold text-forest"} /></Field>
        <Field label={t("rc_ref")} htmlFor="rc-ref"><input id="rc-ref" dir="ltr" maxLength={100} value={ref} onChange={(e) => setRef(e.target.value)} className={inputCls} /></Field>
        <div>
          <p className="mb-1.5 text-sm font-semibold text-soil">{t("rc_photo")}</p>
          {photo && <img src={photo} alt="" className="mb-2 max-h-56 w-full rounded-xl object-contain ring-1 ring-soil/15" />}
          <label className="inline-flex min-h-[44px] cursor-pointer items-center gap-2 rounded-xl border border-forest/30 px-3.5 text-sm font-bold text-forest">
            <Camera className="h-4 w-4" aria-hidden="true" />{t("rc_pick")}
            <input type="file" accept="image/*" onChange={pick} className="sr-only" />
          </label>
        </div>
        {err && <p role="alert" className="rounded-lg bg-red-50 px-3 py-2 text-sm font-semibold text-red-700">{err}</p>}
        <button type="submit" disabled={busy} className="inline-flex min-h-[48px] w-full items-center justify-center gap-2 rounded-xl bg-forest px-4 text-sm font-bold text-ivory disabled:opacity-60"><Receipt className="h-4 w-4" aria-hidden="true" />{busy ? "..." : t("rc_send")}</button>
      </form>
    </SheetModal>
  );
}

// Owner Portal: commission owed on confirmed deals that were paid in cash to the owner
// Signed-out view of the Commission tab: launch promo, commission ladder and Agri-Wallet, never a blank screen
function PublicCommissionCard({ t, onSignIn }) {
  const ladder = [["pub_ladder_machinery", pctLabel(COMMISSION)], ["pub_ladder_crop", pctLabel(CROP_COMMISSION)], ["pub_ladder_land", LAND_COMMISSION_PCT + "%"]];
  const free = [["promo_cat_machinery", PROMO_FREE.machinery], ["promo_cat_crop", PROMO_FREE.crop], ["promo_cat_land", PROMO_FREE.land]];
  return (
    <div className="grid gap-4 lg:grid-cols-3">
      <div className="rounded-2xl bg-gradient-to-br from-forest to-leafink p-4 text-ivory shadow-sm">
        <p className="flex items-center gap-2 font-display text-lg font-extrabold rtl:leading-[2]"><Gift className="h-5 w-5 text-gold" aria-hidden="true" />{t("pub_promo_t")}</p>
        <p className="mt-1 text-xs text-ivory/85 rtl:leading-[2]">{t("pub_promo_s")}</p>
        <ul className="mt-3 grid grid-cols-3 gap-2">
          {free.map(([k, n]) => (
            <li key={k} className="rounded-xl bg-white/10 p-2 text-center ring-1 ring-white/20">
              <p className="font-display text-2xl font-extrabold text-gold tabular-nums" dir="ltr">{n}</p>
              <p className="text-[11px] font-bold rtl:leading-[2]">{t(k)}</p>
            </li>
          ))}
        </ul>
      </div>
      <div className="rounded-2xl border border-soil/10 bg-white p-4 shadow-sm">
        <p className="flex items-center gap-2 font-bold text-forest rtl:leading-[2]"><Percent className="h-4 w-4 text-gold" aria-hidden="true" />{t("pub_ladder_t")}</p>
        <p className="mt-1 text-xs text-soil/80 rtl:leading-[2]">{t("pub_ladder_s")}</p>
        <ul className="mt-3 space-y-2">
          {ladder.map(([k, pct]) => (
            <li key={k} className="flex items-center justify-between gap-2 rounded-xl bg-ivory px-3 py-2 text-sm">
              <span className="font-semibold text-soil rtl:leading-[2]">{t(k)}</span>
              <span className="font-display font-extrabold text-forest tabular-nums" dir="ltr">{pct}</span>
            </li>
          ))}
        </ul>
      </div>
      <div className="flex flex-col rounded-2xl border border-soil/10 bg-white p-4 shadow-sm">
        <p className="flex items-center gap-2 font-bold text-forest rtl:leading-[2]"><Wallet className="h-4 w-4 text-gold" aria-hidden="true" />{t("pub_wallet_t")}</p>
        <p className="mt-1 flex-1 text-sm text-soil/80 rtl:leading-[2]">{t("pub_wallet_s")}</p>
        <button type="button" onClick={onSignIn} className="mt-3 inline-flex min-h-[44px] items-center justify-center gap-2 rounded-xl bg-forest px-4 py-2 text-sm font-bold text-ivory shadow-sm hover:bg-forest/90">
          <LogIn className="h-4 w-4" aria-hidden="true" />{t("pub_signin_btn")}
        </button>
      </div>
    </div>
  );
}

function CommissionLedger({ t, uid, bookings = [], landBookings = [] }) {
  const ctx = useDeals();
  if (!ctx || !uid) return null;
  const deals = [
    ...bookings.filter((b) => b.ownerUid === uid && ["confirmed", "completed", "feedback"].includes(b.status)).map((b) => ({ ...bookingDeal(b), date: b.date })),
    ...landBookings.filter((b) => b.ownerUid === uid && b.status === "accepted").map((b) => ({ ...landDeal(b), date: b.startDate })),
  ].filter((d) => d.amount > 0);
  const stateOf = (d) => { const r = ctx.receipts[dealKeyOf(d)]; return r ? (r.status === "verified" ? "paid" : "review") : "due"; };
  const sum = (st) => deals.filter((d) => stateOf(d) === st).reduce((a, d) => a + d.amount, 0);
  const pill = { due: "bg-red-50 text-red-700 ring-red-200", review: "bg-gold/20 text-soil ring-gold/40", paid: "bg-leaf/15 text-forest ring-leaf/30" };
  return (
    <div className="grid gap-5 lg:grid-cols-[1.4fr_1fr]">
      <div className="rounded-2xl border border-soil/10 bg-white p-4 shadow-sm">
        <h3 className="flex items-center gap-2 font-bold text-forest"><Wallet className="h-4 w-4 text-gold" aria-hidden="true" />{t("cl_title")}</h3>
        <p className="mt-1 text-xs text-soil/80 rtl:leading-[2]">{t("cl_sub")}</p>
        <div className="mt-3 grid grid-cols-3 gap-2">
          {[["due", "cl_due"], ["review", "cl_review"], ["paid", "cl_paid"]].map(([st, k]) => (
            <div key={st} className={`rounded-xl p-2.5 text-center ring-1 ${pill[st]}`}>
              <p className="text-[11px] font-bold uppercase tracking-wide">{t(k)}</p>
              <p className="mt-0.5 font-display text-base font-extrabold tabular-nums" dir="ltr">{pkr(sum(st))}</p>
            </div>
          ))}
        </div>
        {deals.length === 0 ? <p className="mt-3 rounded-xl bg-ivory p-4 text-sm text-soil/80">{t("cl_none")}</p> : (
          <ul className="mt-3 space-y-2">
            {deals.map((d) => {
              const st = stateOf(d);
              return (
                <li key={dealKeyOf(d)} className="rounded-xl bg-ivory p-3 text-sm ring-1 ring-soil/10">
                  <div className="flex flex-wrap items-start justify-between gap-2">
                    <span className="min-w-0">
                      <span className="block font-bold text-forest" dir="auto">{d.title}</span>
                      <span className="text-xs text-soil/80"><span dir="ltr" className="font-mono">{d.id}</span> · {t(d.kind === "land" ? "cl_land" : "cl_machine")}{d.date ? <> · <span dir="ltr">{fmtDate(d.date)}</span></> : null}</span>
                    </span>
                    <span className="flex shrink-0 items-center gap-2">
                      <b className="tabular-nums text-forest" dir="ltr">{pkr(d.amount)}</b>
                      <span className={`rounded-full px-2 py-0.5 text-[11px] font-bold ring-1 ${pill[st]}`}>{t(st === "due" ? "cl_due" : st === "review" ? "cl_review" : "cl_paid")}</span>
                    </span>
                  </div>
                  {st !== "paid" && <div className="mt-2"><ReceiptButton t={t} deal={d} /></div>}
                </li>
              );
            })}
          </ul>
        )}
      </div>
      <CompanyAccountCard t={t} className="h-fit bg-white" />
    </div>
  );
}

// Shared photo / video proof strip on a deal card (only the deal's farmer, owner and the founder see it)
function ProofStrip({ t, deal, className = "" }) {
  const ctx = useDeals();
  const [adding, setAdding] = useState(false);
  const [view, setView] = useState(null);
  if (!isDealParty(ctx, deal)) return null;
  const list = (deal.kind === "land" ? ctx.landProofs : ctx.bookingProofs).filter((p) => p.dealId === deal.id).sort((a, b) => (a.createdAt || 0) - (b.createdAt || 0));
  return (
    <div className={`rounded-xl bg-white p-3 ring-1 ring-soil/10 ${className}`}>
      <div className="flex flex-wrap items-center justify-between gap-2">
        <p className="flex items-center gap-1.5 text-xs font-extrabold uppercase tracking-wide text-forest rtl:leading-[2]"><ShieldCheck className="h-4 w-4 text-leafink" aria-hidden="true" />{t("pf_title")} {list.length ? <span className="rounded-full bg-forest/10 px-1.5 text-[11px]">{list.length}</span> : null}</p>
        <button type="button" onClick={() => setAdding(true)} className="inline-flex min-h-[44px] items-center gap-1.5 rounded-xl border border-forest/30 bg-white px-3 text-xs font-bold text-forest hover:bg-forest/5"><Camera className="h-4 w-4" aria-hidden="true" />{t("pf_add")}</button>
      </div>
      {list.length === 0 ? <p className="mt-2 text-xs text-soil/80 rtl:leading-[2]">{t("pf_none")}</p> : (
        <ul className="no-scrollbar -mx-1 mt-2 flex gap-2 overflow-x-auto px-1 pb-1">
          {list.map((p) => (
            <li key={p.id} className="shrink-0">
              <button type="button" onClick={() => setView(p)} className="group block w-24 text-start" aria-label={t("pf_st_" + p.stage)}>
                <span className="relative block h-20 w-24 overflow-hidden rounded-lg bg-forest/10 ring-1 ring-soil/15">
                  {p.photo ? <img src={p.photo} alt="" className="h-full w-full object-cover" loading="lazy" />
                    : <span className="flex h-full w-full items-center justify-center bg-forest text-ivory"><Play className="h-7 w-7" aria-hidden="true" /></span>}
                  {!p.photo && <span className="absolute bottom-1 start-1 rounded bg-black/50 px-1 text-[10px] font-bold text-white"><Video className="inline h-3 w-3" aria-hidden="true" /></span>}
                </span>
                <span className="mt-1 block truncate text-[11px] font-bold text-soil">{t("pf_st_" + p.stage)}</span>
                <span className="block truncate text-[10px] text-soil/70">{t("pf_by_" + (p.byRole || "admin"))} · <span dir="ltr">{fmtDate(new Date(p.createdAt || Date.now()).toISOString().slice(0, 10))}</span></span>
              </button>
            </li>
          ))}
        </ul>
      )}
      {adding && <ProofModal t={t} deal={deal} onClose={() => setAdding(false)} />}
      {view && (
        <SheetModal title={t("pf_st_" + view.stage)} onClose={() => setView(null)} labelledBy="pf-view-h">
          {view.photo && <img src={view.photo} alt={t("pf_st_" + view.stage)} className="w-full rounded-xl object-contain ring-1 ring-soil/15" />}
          {view.video && <video src={view.video} controls playsInline className="w-full rounded-xl bg-black" />}
          {view.videoUrl && <a href={view.videoUrl} target="_blank" rel="noopener noreferrer" className="mt-2 inline-flex min-h-[44px] items-center gap-2 rounded-xl bg-forest px-4 text-sm font-bold text-ivory"><ExternalLink className="h-4 w-4" aria-hidden="true" />{t("pf_open_link")}</a>}
          {view.note && <p className="mt-3 rounded-xl bg-ivory p-3 text-sm text-soil" dir="auto">{view.note}</p>}
          <p className="mt-2 text-xs text-soil/80">{t("pf_by_" + (view.byRole || "admin"))}{view.byName ? ` (${view.byName})` : ""} · <span dir="ltr">{new Date(view.createdAt || Date.now()).toLocaleString("en-PK")}</span></p>
        </SheetModal>
      )}
    </div>
  );
}

function ProofModal({ t, deal, onClose }) {
  const ctx = useDeals();
  const [stage, setStage] = useState(deal.kind === "land" ? "land" : "before");
  const [photo, setPhoto] = useState("");
  const [video, setVideo] = useState("");
  const [videoUrl, setVideoUrl] = useState("");
  const [note, setNote] = useState("");
  const [err, setErr] = useState("");
  const [busy, setBusy] = useState(false);
  const pick = (e) => {
    const file = e.target.files && e.target.files[0];
    e.target.value = "";
    if (!file) return;
    setErr("");
    if (/^video\//.test(file.type || "")) {
      if (file.size > PROOF_VIDEO_MAX) { setErr(t("pf_video_big")); return; }
      readFileAsDataUrl(file).then((v) => { setVideo(v); setPhoto(""); }).catch(() => setErr(t("pf_err")));
      return;
    }
    shrinkPhoto(file).then((v) => { setPhoto(v); setVideo(""); }).catch(() => setErr(t("ow_photo_err")));
  };
  const submit = (e) => {
    e.preventDefault();
    const url = videoUrl.trim();
    if (url && !/^https:\/\/\S+$/i.test(url)) { setErr(t("pf_bad_url")); return; }
    if (!photo && !video && !url) { setErr(t("pf_need")); return; }
    if (!isDealParty(ctx, deal)) { setErr(t("rc_not_party")); return; }
    setBusy(true);
    const uid = ctx.session.uid;
    const doc = {
      id: `${deal.id}_${Date.now().toString(36)}${Math.random().toString(36).slice(2, 6)}`,
      dealId: deal.id, kind: deal.kind, stage, uids: deal.uids, byUid: uid, byName: ctx.session.name || "",
      byRole: uid === deal.farmerUid ? "farmer" : uid === deal.ownerUid ? "owner" : "admin", createdAt: Date.now(),
      ...(photo ? { photo } : {}), ...(video ? { video } : {}), ...(url ? { videoUrl: url.slice(0, 480) } : {}), ...(note.trim() ? { note: note.trim().slice(0, 280) } : {}),
    };
    ctx.addProof(doc).then(() => { ctx.toast(t("pf_saved")); onClose(); }).catch(() => { setBusy(false); setErr(t("pf_err")); });
  };
  return (
    <SheetModal title={t("pf_add")} onClose={onClose} labelledBy="pf-h">
      <form onSubmit={submit} noValidate className="space-y-4">
        <fieldset>
          <legend className="mb-1.5 text-sm font-semibold text-soil">{t("pf_stage")}</legend>
          <div className="grid grid-cols-2 gap-2">
            {PROOF_STAGES.map((k) => (
              <label key={k} className={`flex min-h-[48px] cursor-pointer items-center rounded-xl px-3 py-2 text-sm font-bold leading-snug ring-1 rtl:leading-[2] ${stage === k ? "bg-forest text-ivory ring-forest" : "bg-white text-forest ring-soil/20"}`}>
                <input type="radio" name="pf-stage" value={k} checked={stage === k} onChange={() => setStage(k)} className="sr-only" />{t("pf_st_" + k)}
              </label>
            ))}
          </div>
        </fieldset>
        <div>
          <p className="mb-1.5 text-sm font-semibold text-soil">{t("pf_file")}</p>
          {photo && <img src={photo} alt="" className="mb-2 max-h-56 w-full rounded-xl object-contain ring-1 ring-soil/15" />}
          {video && <video src={video} controls playsInline className="mb-2 max-h-56 w-full rounded-xl bg-black" />}
          <label className="inline-flex min-h-[44px] cursor-pointer items-center gap-2 rounded-xl border border-forest/30 px-3.5 text-sm font-bold text-forest">
            <Camera className="h-4 w-4" aria-hidden="true" />{t("rc_pick")}
            <input type="file" accept="image/*,video/*" onChange={pick} className="sr-only" />
          </label>
          <p className="mt-1.5 text-[11px] text-soil/80 rtl:leading-[2]">{t("pf_file_hint")}</p>
        </div>
        <Field label={t("pf_url")} htmlFor="pf-url"><input id="pf-url" type="url" dir="ltr" placeholder="https://" value={videoUrl} onChange={(e) => setVideoUrl(e.target.value)} className={inputCls} /></Field>
        <Field label={t("pf_note")} htmlFor="pf-note"><input id="pf-note" maxLength={280} value={note} onChange={(e) => setNote(e.target.value)} className={inputCls} /></Field>
        {err && <p role="alert" className="rounded-lg bg-red-50 px-3 py-2 text-sm font-semibold text-red-700">{err}</p>}
        <button type="submit" disabled={busy} className="inline-flex min-h-[48px] w-full items-center justify-center gap-2 rounded-xl bg-forest px-4 text-sm font-bold text-ivory disabled:opacity-60"><Upload className="h-4 w-4" aria-hidden="true" />{busy ? "..." : t("pf_save")}</button>
      </form>
    </SheetModal>
  );
}

// Admin Panel: the official account (founder only) and the commission receipts to verify
function CompanyPaymentAdmin({ t, isFounder }) {
  const ctx = useDeals();
  const blank = { bankName: "", accountTitle: "", iban: "", jazzcash: "", easypaisa: "", raast: "" };
  const fromDoc = (c) => ({ ...blank, ...Object.fromEntries(Object.keys(blank).map((k) => [k, (c && c[k]) || ""])) });
  const hasSaved = (c) => !!c && Object.keys(blank).some((k) => String(c[k] || "").trim());
  const [f, setF] = useState(blank);
  const [editing, setEditing] = useState(false);
  const [saving, setSaving] = useState(false);
  const loaded = useRef(false);
  useEffect(() => {
    if (!loaded.current && ctx && ctx.company) { loaded.current = true; setF(fromDoc(ctx.company)); }
  }, [ctx && ctx.company]); // eslint-disable-line react-hooks/exhaustive-deps
  const saved = hasSaved(ctx && ctx.company);
  const open = editing || !saved; // nothing saved yet: show the form straight away
  const save = (e) => {
    e.preventDefault();
    if (!isFounder) { ctx.toast(t("ad_founder_only"), { type: "error" }); return; }
    const clean = Object.fromEntries(Object.entries(f).map(([k, v]) => [k, String(v || "").trim().slice(0, 60)]));
    setSaving(true);
    ctx.saveCompany(clean)
      .then(() => { setF(fromDoc(clean)); setEditing(false); ctx.toast(t("ad_cp_saved")); })
      .catch(() => ctx.toast(t("rc_err"), { type: "error" }))
      .finally(() => setSaving(false));
  };
  const cancel = () => { setF(fromDoc(ctx && ctx.company)); setEditing(false); };
  const field = (k, label) => (
    <label key={k} className="text-xs font-bold text-soil" htmlFor={"cp-" + k}>{t(label)}
      <input id={"cp-" + k} dir="ltr" maxLength={60} value={f[k]} onChange={(e) => setF((s) => ({ ...s, [k]: e.target.value }))} className={inputCls + " mt-1"} />
    </label>
  );
  const c = (ctx && ctx.company) || {};
  const rows = [["bankName", "ca_bank"], ["accountTitle", "ca_acc_title"], ["iban", "ca_iban"], ["raast", "ca_raast"], ["jazzcash", "ca_jazz"], ["easypaisa", "ca_easy"]].filter(([k]) => String(c[k] || "").trim());
  const head = (
    <>
      <h3 className="flex items-center gap-2 font-bold text-forest"><Landmark className="h-4 w-4" aria-hidden="true" />{t("ad_cp_t")}</h3>
      <p className="mt-1 text-xs text-soil/80">{t("ad_cp_sub")}</p>
    </>
  );
  if (!open) {
    return (
      <div className="rounded-2xl border border-soil/10 bg-white p-5 shadow-sm">
        {head}
        <div className="mt-4 rounded-xl bg-ivory p-3 ring-1 ring-leaf/30">
          <p className="mb-2 flex items-center gap-1.5 text-xs font-bold text-leaf"><CircleCheck className="h-4 w-4" aria-hidden="true" />{t("ad_cp_saved_badge")}</p>
          <dl className="grid gap-x-4 gap-y-1.5 text-sm sm:grid-cols-2">
            {rows.map(([k, label]) => (
              <div key={k} className="min-w-0">
                <dt className="text-[11px] font-semibold text-soil/70">{t(label)}</dt>
                <dd dir="ltr" className="truncate text-start font-bold text-forest">{c[k]}</dd>
              </div>
            ))}
          </dl>
        </div>
        {isFounder ? (
          <button type="button" onClick={() => { setF(fromDoc(c)); setEditing(true); }} className="mt-3 inline-flex min-h-[44px] items-center gap-2 rounded-xl px-4 text-sm font-bold text-forest ring-1 ring-forest/30 hover:bg-forest/5">
            <Pencil className="h-4 w-4" aria-hidden="true" />{t("ad_cp_edit")}
          </button>
        ) : <p className="mt-2 text-xs font-semibold text-soil/80">{t("ad_founder_only")}</p>}
      </div>
    );
  }
  return (
    <form onSubmit={save} className="rounded-2xl border border-soil/10 bg-white p-5 shadow-sm">
      {head}
      <fieldset disabled={!isFounder || saving} className="mt-4 grid gap-2 sm:grid-cols-2 disabled:opacity-60">
        {field("bankName", "ca_bank")}{field("accountTitle", "ca_acc_title")}
        <div className="sm:col-span-2">{field("iban", "ca_iban")}</div>
        {field("jazzcash", "ca_jazz")}{field("easypaisa", "ca_easy")}{field("raast", "ca_raast")}
        <div className="flex gap-2 sm:col-span-2">
          <button type="submit" className="min-h-[44px] flex-1 rounded-xl bg-forest px-5 text-sm font-bold text-ivory">{t("ad_cp_save")}</button>
          {saved && <button type="button" onClick={cancel} className="min-h-[44px] rounded-xl px-4 text-sm font-bold text-soil ring-1 ring-soil/20 hover:bg-soil/5">{t("ad_cp_cancel")}</button>}
        </div>
      </fieldset>
      {!isFounder && <p className="mt-2 text-xs font-semibold text-soil/80">{t("ad_founder_only")}</p>}
    </form>
  );
}

function ReceiptsAdmin({ t, isFounder }) {
  const ctx = useDeals();
  const [view, setView] = useState(null);
  const list = Object.values((ctx && ctx.receipts) || {}).sort((a, b) => (a.status === "pending" ? 0 : 1) - (b.status === "pending" ? 0 : 1) || (b.updatedAt || 0) - (a.updatedAt || 0));
  const toggle = (r) => {
    if (!isFounder) { ctx.toast(t("ad_founder_only"), { type: "error" }); return; }
    ctx.verifyReceipt(r, r.status !== "verified").catch(() => ctx.toast(t("rc_err"), { type: "error" }));
  };
  return (
    <div className="rounded-2xl border border-soil/10 bg-white p-5 shadow-sm lg:col-span-2">
      <h3 className="flex items-center gap-2 font-bold text-forest"><Receipt className="h-4 w-4" aria-hidden="true" />{t("ad_rc_t")}</h3>
      <p className="mt-1 text-xs text-soil/80">{t("ad_rc_sub")}</p>
      {list.length === 0 ? <p className="mt-3 rounded-xl bg-ivory p-4 text-sm text-soil/80">{t("ad_rc_none")}</p> : (
        <ul className="mt-3 grid gap-2 md:grid-cols-2">
          {list.map((r) => (
            <li key={r.dealKey || r.id} className="flex gap-3 rounded-xl bg-ivory p-3 text-sm ring-1 ring-soil/10">
              <button type="button" onClick={() => setView(r)} className="h-16 w-16 shrink-0 overflow-hidden rounded-lg ring-1 ring-soil/15" aria-label={t("rc_photo")}>{r.photo ? <img src={r.photo} alt="" className="h-full w-full object-cover" /> : <Receipt className="m-auto h-6 w-6 text-soil/40" />}</button>
              <div className="min-w-0 flex-1">
                <p className="font-bold text-forest"><span dir="ltr" className="font-mono">{r.dealId}</span> · {t(r.kind === "land" ? "cl_land" : "cl_machine")}</p>
                <p className="text-xs text-soil/80">{t("ad_rc_from")}: {r.byName || "-"} · <b dir="ltr">{pkr(r.amount || 0)}</b>{r.ref ? <> · <span dir="ltr" className="font-mono">{r.ref}</span></> : null}</p>
                <label className="mt-2 flex min-h-[44px] cursor-pointer items-center gap-2 text-xs font-bold text-forest">
                  <input type="checkbox" checked={r.status === "verified"} disabled={!isFounder} onChange={() => toggle(r)} className="h-5 w-5 accent-[#145A32]" />
                  {t("ad_rc_verify")}
                </label>
              </div>
            </li>
          ))}
        </ul>
      )}
      {view && <SheetModal title={t("rc_title")} onClose={() => setView(null)} labelledBy="ad-rc-h"><img src={view.photo} alt={t("rc_photo")} className="w-full rounded-xl object-contain ring-1 ring-soil/15" /></SheetModal>}
    </div>
  );
}

function voucherSteps(b) {
  const stopped = ["declined", "cancelled"].includes(b.status);
  const confirmed = ["confirmed", "completed", "feedback"].includes(b.status);
  const done = ["completed", "feedback"].includes(b.status);
  const enRoute = done || (confirmed && (b.enRouteAt || (b.date && b.date <= todayISO())));
  return { stopped, steps: [confirmed, !!enRoute, done] };
}

function VoucherModal({ b, t, dn, onClose, updateBooking }) {
  const ref = useRef(null);
  useEffect(() => {
    const k = (e) => { if (e.key === "Escape") onClose(); };
    window.addEventListener("keydown", k);
    return () => window.removeEventListener("keydown", k);
  }, [onClose]);
  if (!b) return null;
  const q = b.quote || {};
  const code = voucherCode(b);
  const { stopped, steps } = voucherSteps(b);
  const cur = steps.indexOf(false);
  const rows = [
    [t("bk_base") + ` (${q.hours || b.hours} h × ${pkr(q.rate || 0)})`, q.base],
    q.operator ? [t("bk_op"), q.operator] : null,
    q.transport ? [t("bk_tr"), q.transport] : null,
    q.fuel ? [t("vo_fuel"), q.fuel] : null,
    [commLabel(t, q), q.commission],
  ].filter(Boolean).filter((r) => r[1] != null);
  const print = () => {
    document.body.classList.add("print-voucher");
    const done = () => { document.body.classList.remove("print-voucher"); window.removeEventListener("afterprint", done); };
    window.addEventListener("afterprint", done);
    setTimeout(() => { try { window.print(); } catch (e) { done(); } }, 50);
  };
  const download = async () => {
    const css = "body{font-family:system-ui,-apple-system,Segoe UI,sans-serif;background:#FAF8EE;color:#5C3A21;margin:0;padding:24px}.v{max-width:640px;margin:auto;background:#fff;border-radius:20px;border:1px solid #e7e2d3;overflow:hidden}.h{background:#145A32;color:#FAF8EE;padding:20px 24px}.h b{color:#E6B325}.p{padding:20px 24px}table{width:100%;border-collapse:collapse;font-size:14px}td{padding:6px 0;border-bottom:1px solid #f0ebdd}td:last-child{text-align:right;font-weight:700}.tot td{font-size:18px;color:#145A32;border:0}.muted{color:#8a7563;font-size:12px}svg{display:block}";
    const html = `<!DOCTYPE html><html><head><meta charset="utf-8"><title>PakAgriShare voucher ${code}</title><style>${css}</style></head><body>${ref.current ? ref.current.outerHTML.replace(/class="[^"]*"/g, "") : ""}</body></html>`;
    const filename = `PakAgriShare-voucher-${code.replace("#", "")}.html`;
    // inside claude.ai the page must ask the viewer through the downloads capability
    if (typeof window !== "undefined" && window.claude && typeof window.claude.use === "function") {
      try { const dl = await window.claude.use("downloads"); if (dl) { await dl.save({ filename, data: html }); return; } } catch (e) { return; }
    }
    const blob = new Blob([html], { type: "text/html" });
    const a = document.createElement("a");
    a.href = URL.createObjectURL(blob); a.download = filename;
    document.body.appendChild(a); a.click(); setTimeout(() => { URL.revokeObjectURL(a.href); a.remove(); }, 500);
  };
  return createPortal(
    <div id="voucher-root" className="fixed inset-0 z-[85] flex items-end justify-center bg-soil/50 backdrop-blur-sm sm:items-center sm:p-4" onClick={onClose}>
      <div className="sheet-in max-h-[94vh] w-full max-w-xl overflow-y-auto rounded-t-3xl bg-ivory shadow-2xl sm:rounded-3xl" onClick={(e) => e.stopPropagation()} role="dialog" aria-modal="true" aria-labelledby="vo-h">
        <div ref={ref} className="voucher-card overflow-hidden bg-white sm:m-4 sm:rounded-2xl sm:ring-1 sm:ring-soil/10">
          <div className="h relative overflow-hidden bg-forest px-5 py-5 text-ivory">
            <div className="pointer-events-none absolute -end-10 -top-10 h-40 w-40 rounded-full bg-gold/20 blur-2xl" aria-hidden="true" />
            <div className="relative flex items-start justify-between gap-3">
              <div>
                <p className="text-[11px] font-bold uppercase tracking-[0.18em] text-gold">PakAgriShare</p>
                <h2 id="vo-h" className="font-display text-xl font-extrabold">{t("vo_title")}</h2>
                <p className="mt-1 font-mono text-lg font-bold tracking-wider text-gold" dir="ltr"><b>{code}</b></p>
                <p className="muted text-xs text-ivory/80" dir="ltr">{t("vo_ref")}: {b.id} · {t("vo_issued")} {fmtDate(new Date(b.createdAt || Date.now()).toISOString().slice(0, 10))}</p>
              </div>
              <div className="shrink-0 rounded-xl bg-white p-1.5 shadow-lg"><VerifyPattern seed={b.id + "|" + b.createdAt} size={92} /></div>
            </div>
          </div>
          <div className="p space-y-4 p-5">
            <div className={`flex items-center gap-2 rounded-xl px-3 py-2 text-sm font-bold ${stopped ? "bg-red-50 text-red-700" : "bg-leaf/10 text-forest"}`}>
              {stopped ? <X className="h-4 w-4" aria-hidden="true" /> : <ShieldCheck className="h-4 w-4" aria-hidden="true" />}
              {stopped ? t("vo_cancelled") : t("vo_verified")}
            </div>
            {!stopped && (
              <div>
                <p className="mb-2 text-xs font-bold uppercase tracking-wide text-soil/80">{t("vo_track")}</p>
                <ol className="grid grid-cols-3 gap-1">
                  {[t("vo_s1"), t("vo_s2"), t("vo_s3")].map((label, i) => (
                    <li key={label} className="flex flex-col items-center text-center">
                      <div className="flex w-full items-center">
                        <span className={`h-1 flex-1 rounded ${i === 0 ? "invisible" : steps[i] ? "bg-leaf" : "bg-soil/15"}`} />
                        <span className={`flex h-8 w-8 shrink-0 items-center justify-center rounded-full text-xs font-bold transition ${steps[i] ? "bg-leafink text-white" : i === cur ? "bg-gold text-soil ring-4 ring-gold/25" : "bg-soil/10 text-soil/80"}`}>
                          {steps[i] ? <Check className="h-4 w-4" aria-hidden="true" /> : i === 1 ? <Truck className="h-4 w-4" aria-hidden="true" /> : i + 1}
                        </span>
                        <span className={`h-1 flex-1 rounded ${i === 2 ? "invisible" : steps[i + 1] ? "bg-leaf" : "bg-soil/15"}`} />
                      </div>
                      <span className={`mt-1 text-[11px] font-semibold leading-tight ${steps[i] ? "text-forest" : i === cur ? "text-soil" : "text-soil/80"}`}>{label}</span>
                    </li>
                  ))}
                </ol>
                {cur === 0 && <p className="mt-2 text-center text-xs text-soil/80">{t("vo_waiting")}</p>}
                {cur === 1 && updateBooking && <div className="mt-2 text-center"><button onClick={() => updateBooking(b.id, b.status, { enRouteAt: Date.now() }, true)} className="rounded-lg bg-forest/5 px-3 py-1.5 text-xs font-bold text-forest hover:bg-forest/10">{t("vo_mark_route")}</button></div>}
              </div>
            )}
            <dl className="grid grid-cols-2 gap-x-4 gap-y-2 text-sm">
              {[[t("vo_machine"), b.listingName], [t("vo_date"), fmtDate(b.date) + " · " + (q.hours || b.hours) + " h"], [t("owner"), b.ownerId], [t("vo_location"), dn ? dn(b.district || "") : b.district], [t("vo_renter"), b.renterName || "-"],
                [t("bk_op"), b.operator === true ? t("vo_op_included") : t("vo_op_agreed")],
                [t("bk_pay"), b.payment && b.payment !== "direct" && T.en["pay_" + b.payment] ? t("pay_" + b.payment) : t("vo_pay_direct")]].map(([k, v]) => (
                <div key={k} className="min-w-0"><dt className="text-[11px] font-semibold uppercase tracking-wide text-soil/80">{k}</dt><dd className="truncate font-bold text-soil" dir="auto">{v}</dd></div>
              ))}
            </dl>
            <div className="rounded-xl bg-ivory/70 p-3 ring-1 ring-soil/10">
              <p className="mb-1 text-xs font-bold uppercase tracking-wide text-soil/80">{t("vo_items")}</p>
              <table className="w-full text-sm"><tbody>
                {rows.map(([k, v]) => <tr key={k} className="border-b border-soil/10"><td className="py-1.5 text-soil/80">{k}</td><td className="py-1.5 text-end font-semibold" dir="ltr">{pkr(v)}</td></tr>)}
                <tr className="tot"><td className="pt-2 font-display text-base font-extrabold text-forest">{t("vo_total")}</td><td className="pt-2 text-end font-display text-xl font-extrabold text-forest" dir="ltr">{pkr(q.total || 0)}</td></tr>
              </tbody></table>
              {b.financing && <p className="mt-2 text-xs text-soil/80" dir="ltr">{t("pay_paylater")}: {t("pl_now")} <b>{pkr(b.financing.advance)}</b> · {t("pl_later")} <b>{pkr(b.financing.balance)}</b> ({b.financing.partner})</p>}
            </div>
            <CommissionSplit t={t} commission={q.commission} total={q.total} promo={q.promo} />
            {b.walletPaid ? <p className="flex items-center gap-2 rounded-xl bg-leaf/10 p-3 text-sm font-bold text-forest ring-1 ring-leaf/30 rtl:leading-[2]"><Wallet className="h-4 w-4 shrink-0" aria-hidden="true" />{t("aw_paid")}</p>
              : !stopped && !q.promo && <CompanyAccountCard t={t} deal={bookingDeal(b)} />}
            {!stopped && <div className="no-print"><ProofStrip t={t} deal={bookingDeal(b)} /></div>}
            <p className="muted text-[11px] leading-snug text-soil/80">{t("vo_note")} {t("vo_pattern_note")}</p>
          </div>
        </div>
        <div className="no-print sticky bottom-0 flex flex-wrap gap-2 border-t border-soil/10 bg-ivory/95 p-4 backdrop-blur">
          <button onClick={print} className="min-h-[44px] inline-flex flex-1 items-center justify-center gap-2 rounded-xl bg-forest px-4 py-2.5 text-sm font-bold text-ivory transition hover:bg-[#0f4a28]"><Printer className="h-4 w-4" aria-hidden="true" />{t("vo_print")}</button>
          <button onClick={download} className="min-h-[44px] inline-flex flex-1 items-center justify-center gap-2 rounded-xl bg-white px-4 py-2.5 text-sm font-bold text-forest ring-1 ring-forest/20 transition hover:bg-forest/5"><Download className="h-4 w-4" aria-hidden="true" />{t("vo_download")}</button>
          <button onClick={onClose} aria-label="Close voucher" className="min-h-[44px] inline-flex items-center justify-center rounded-xl px-4 py-2.5 text-sm font-bold text-soil ring-1 ring-soil/15 transition hover:bg-white">{t("vo_close")}</button>
        </div>
      </div>
    </div>,
    document.body
  );
}

/* ------------------------------------------------------------------ */
/* My Activity drawer: bookings, live requests and Agri-Market deals   */
/* ------------------------------------------------------------------ */
function ActivityDrawer({ t, dn, open, onClose, bookings, requests, deals, onVoucher, setTab }) {
  const [view, setView] = useState("bookings");
  useEffect(() => {
    if (!open) return undefined;
    const k = (e) => { if (e.key === "Escape") onClose(); };
    window.addEventListener("keydown", k);
    return () => window.removeEventListener("keydown", k);
  }, [open, onClose]);
  if (!open) return null;
  const tabs = [["bookings", t("act_bookings"), bookings.length], ["requests", t("act_requests"), requests.length], ["deals", t("act_deals"), deals.length]];
  const go = (k) => { onClose(); setTab(k); };
  const Empty = ({ text, cta, to }) => (
    <div className="flex flex-col items-center gap-3 rounded-2xl bg-white p-8 text-center ring-1 ring-soil/10">
      <span className="flex h-12 w-12 items-center justify-center rounded-2xl bg-forest/10 text-forest"><Inbox className="h-6 w-6" aria-hidden="true" /></span>
      <p className="text-sm text-soil/80">{text}</p>
      <button onClick={() => go(to)} className="rounded-xl bg-forest px-4 py-2 text-sm font-bold text-ivory">{cta}</button>
    </div>
  );
  return createPortal(
    <div className="fixed inset-0 z-[75] flex justify-end bg-soil/40 backdrop-blur-sm" onClick={onClose}>
      <aside className="drawer-in flex h-full w-full max-w-md flex-col bg-ivory shadow-2xl" onClick={(e) => e.stopPropagation()} role="dialog" aria-modal="true" aria-labelledby="act-h">
        <div className="flex items-center justify-between gap-2 border-b border-soil/10 bg-white/80 px-5 py-4 backdrop-blur">
          <div>
            <h2 id="act-h" className="font-display text-xl font-extrabold text-forest">{t("act_title")}</h2>
            <p className="text-xs text-soil/80">{t("act_sub")}</p>
          </div>
          <button onClick={onClose} className="rounded-xl p-2 text-soil/80 hover:bg-soil/5" aria-label={t("vo_close")}><X className="h-5 w-5" /></button>
        </div>
        <div className="flex gap-1 border-b border-soil/10 bg-white/60 px-3 py-2" role="tablist">
          {tabs.map(([k, label, n]) => (
            <button key={k} role="tab" aria-selected={view === k} onClick={() => setView(k)} className={`flex min-h-[44px] flex-1 items-center justify-center gap-1.5 rounded-xl px-2 py-2 text-sm font-bold transition ${view === k ? "bg-forest text-ivory shadow" : "text-soil/80 hover:bg-soil/5"}`}>
              {label}<span className={`rounded-full px-1.5 text-[11px] ${view === k ? "bg-ivory/20" : "bg-soil/10"}`}>{n}</span>
            </button>
          ))}
        </div>
        <div className="flex-1 space-y-2.5 overflow-y-auto p-4">
          {view === "bookings" && (bookings.length ? bookings.map((b) => (
            <button key={b.id} onClick={() => onVoucher(b.id)} className="flex w-full items-center gap-3 rounded-2xl bg-white p-3 text-start shadow-sm ring-1 ring-soil/10 transition-all duration-300 hover:-translate-y-0.5 hover:shadow-md">
              <MachinePhoto category={b.category} name={b.listingName} className="h-14 w-16 shrink-0 rounded-xl" alt="" width={128} height={112} />
              <span className="min-w-0 flex-1">
                <span className="block truncate font-bold text-forest">{b.listingName}</span>
                <span className="block truncate text-xs text-soil/80" dir="ltr">{voucherCode(b)} · {fmtDate(b.date)} · {pkr((b.quote && b.quote.total) || 0)}</span>
                <span className="mt-1 inline-block"><StatusPill status={b.status} t={t} /></span>
              </span>
              <span className="flex shrink-0 flex-col items-center text-[10px] font-bold text-forest"><Ticket className="h-5 w-5" aria-hidden="true" />{t("act_voucher")}</span>
            </button>
          )) : <Empty text={t("act_empty_b")} cta={t("nav_market")} to="marketplace" />)}
          {view === "requests" && (requests.length ? requests.map((r) => (
            <button key={r.id} onClick={() => go("live-request")} className="flex w-full items-center gap-3 rounded-2xl bg-white p-3 text-start shadow-sm ring-1 ring-soil/10 transition-all duration-300 hover:-translate-y-0.5 hover:shadow-md">
              <span className="flex h-12 w-12 shrink-0 items-center justify-center rounded-xl bg-forest/10 text-forest"><Radar className="h-6 w-6" aria-hidden="true" /></span>
              <span className="min-w-0 flex-1">
                <span className="block truncate font-bold text-forest">{t("one_" + r.category)} · {r.village}</span>
                <span className="block truncate text-xs text-soil/80" dir="ltr">{r.id} · {fmtDate(r.date)} · {pkr(r.rate)}/hr · T{r.tierReached || 1}</span>
              </span>
              <span className={`shrink-0 rounded-full px-2 py-0.5 text-[11px] font-bold ${r.status === "booked" ? "bg-leaf/15 text-forest" : r.status === "open" ? "bg-gold/25 text-soil" : "bg-soil/10 text-soil/80"}`}>{t("rq_" + r.status)}</span>
            </button>
          )) : <Empty text={t("act_empty_r")} cta={t("nav_live")} to="live-request" />)}
          {view === "deals" && (deals.length ? deals.map((p) => (
            <button key={p.id} onClick={() => go("agri-mandi")} className="flex w-full items-center gap-3 rounded-2xl bg-white p-3 text-start shadow-sm ring-1 ring-soil/10 transition-all duration-300 hover:-translate-y-0.5 hover:shadow-md">
              <span className="flex h-12 w-12 shrink-0 items-center justify-center rounded-xl bg-gold/20 text-soil"><Wheat className="h-6 w-6" aria-hidden="true" /></span>
              <span className="min-w-0 flex-1">
                <span className="block truncate font-bold text-forest">{cropName(t, p)} · {p.qty} {t("am_mann")}</span>
                <span className="block truncate text-xs text-soil/80" dir="ltr">{p.id} · {pkr(p.rate)} / {t("am_mann")}{p.sale ? ` · ${pkr(p.sale.gross || 0)}` : ""}</span>
              </span>
              <span className={`shrink-0 rounded-full px-2 py-0.5 text-[11px] font-bold ${p.status === "sold" ? "bg-leaf/15 text-forest" : "bg-gold/25 text-soil"}`}>{p.status === "sold" ? t("act_sold") : t("act_open")}</span>
            </button>
          )) : <Empty text={t("act_empty_d")} cta={t("nav_mandi")} to="agri-mandi" />)}
        </div>
        <div className="border-t border-soil/10 bg-white/80 p-3 text-center">
          <button onClick={() => go("bookings")} className="text-sm font-bold text-forest underline-offset-2 hover:underline">{t("act_all")}</button>
        </div>
      </aside>
    </div>,
    document.body
  );
}

/* ------------------------------------------------------------------ */
/* Marketplace                                                         */
/* ------------------------------------------------------------------ */
function ListingCard({ l, t, dn, lang, onBook }) {
  const opText = l.operator === "included" ? t("op_included") : l.operator === "optional" ? t("op_optional") : t("op_none");
  const trText = l.transport === "included" ? t("tr_included") : l.transport === "optional" ? t("tr_fee").replace("{fee}", pkr(transportFee(l.distance))).replace("{km}", l.distance) : t("tr_self");
  return (
    <article className="group flex flex-col overflow-hidden rounded-2xl border border-soil/10 bg-white shadow-sm ring-1 ring-transparent transition-all duration-300 hover:-translate-y-1 hover:shadow-xl hover:shadow-forest/10 hover:ring-forest/10">
      <div className="relative aspect-video overflow-hidden text-ivory">
        {/^data:image\/(jpeg|png|webp);base64,/.test(String(l.photo || ""))
          ? <img src={l.photo} alt={l.name} width={640} height={360} loading="lazy" decoding="async" className="h-full w-full bg-forest/20 object-cover transition-transform duration-500 group-hover:scale-105" />
          : <MachinePhoto category={l.category} name={l.name} className="h-full w-full transition-transform duration-500 group-hover:scale-105" alt={l.name} />}
        <div className="absolute start-3 end-3 top-3 flex flex-wrap gap-1.5">
          {l.spec && <span className="rounded-full bg-black/45 px-2 py-0.5 text-[11px] font-bold text-white ring-1 ring-white/25 backdrop-blur-md" dir="ltr">{String(l.spec).split(/[,·]/)[0].trim().slice(0, 22)}</span>}
          <span className="rounded-full bg-gold/90 px-2 py-0.5 text-[11px] font-bold text-soil backdrop-blur-md">{t("ov_dry")}</span>
          {l.operator === "included" && <span className="rounded-full bg-white/85 px-2 py-0.5 text-[11px] font-bold text-forest backdrop-blur-md">{t("ov_op")}</span>}
        </div>
        <div className="absolute inset-x-0 bottom-0 bg-gradient-to-t from-black/85 via-black/45 to-transparent px-4 pb-3 pt-12">
          <p className="flex items-center gap-1.5 text-[11px] font-bold uppercase tracking-wider text-ivory/85"><CategoryIcon category={l.category} className="h-3.5 w-3.5 text-gold" />{t("one_" + l.category)}</p>
          <h3 className="break-words font-display text-base font-extrabold leading-tight" title={l.name}>{l.name}</h3>
        </div>
        {l.isVerified ? (
          <span className="absolute end-3 top-3 inline-flex items-center gap-1 rounded-full bg-white/95 px-2 py-0.5 text-[10px] font-bold text-forest shadow"><BadgeCheck className="h-3 w-3" aria-hidden="true" />{t("ls_verified")}</span>
        ) : (l.status || "approved") === "approved" && l.ownerUid ? (
          <span className="absolute end-3 top-3 rounded-full bg-gold px-2 py-0.5 text-[10px] font-bold text-soil shadow">{t("ls_unverified")}</span>
        ) : null}
      </div>
      <div className="flex flex-1 flex-col gap-3 p-4">
        <div>
          <p className="text-[11px] font-semibold uppercase tracking-wide text-soil/80">{t("rate_label")}</p>
          <p className="flex flex-wrap items-baseline font-display text-2xl font-extrabold text-forest"><span dir="ltr">{pkr(l.rate)}</span><span className="text-sm font-semibold text-soil/80">{t("per_hour")}</span></p>
          <p className="mt-1.5 inline-flex items-start gap-1.5 rounded-lg bg-gold/15 px-2.5 py-1 text-[11px] font-bold leading-snug text-soil ring-1 ring-gold/40 rtl:leading-[2]"><Tag className="mt-0.5 h-3.5 w-3.5 shrink-0 text-gold" aria-hidden="true" />{t("ask_rate_badge")}</p>
        </div>
        <div className="flex flex-wrap items-center gap-2">
          <span className="inline-flex shrink-0 items-center gap-1 whitespace-nowrap rounded-full bg-ivory px-2.5 py-1 text-sm font-bold text-soil ring-1 ring-soil/10">
            <MapPin className="h-4 w-4 text-leafink" aria-hidden="true" /><span dir="ltr">{l.distance}</span> {t("km")}{l.fromPin && <span className="text-[10px] font-semibold text-soil/80">({t("loc_road")})</span>}
          </span>
          <span className="text-xs text-soil/80">{l.village}, {dn(l.district)}{l.province && l.province !== "PB" ? `, ${provLabel(lang, l.country, l.province)}` : ""}</span>
        </div>
        <p className="inline-flex w-fit items-center gap-1.5 rounded-lg bg-gold/15 px-2.5 py-1 text-xs font-bold text-soil ring-1 ring-gold/40">
          <Fuel className="h-3.5 w-3.5" aria-hidden="true" />{t("dry_rent")}
        </p>
        <ul className="space-y-1.5 text-sm text-soil/90">
          <li className="flex items-start gap-2"><User className="mt-0.5 h-4 w-4 shrink-0 text-leafink" aria-hidden="true" />{opText}</li>
          <li className="flex items-start gap-2"><Truck className="mt-0.5 h-4 w-4 shrink-0 text-leafink" aria-hidden="true" />{trText}</li>
          {l.spec && <li className="flex items-start gap-2"><Info className="mt-0.5 h-4 w-4 shrink-0 text-leafink" aria-hidden="true" /><span dir="ltr">{l.spec}</span></li>}
        </ul>
        <div className="mt-auto flex flex-wrap items-center justify-between gap-2 border-t border-soil/10 pt-3 text-xs text-soil/80">
          <span className="inline-flex items-center gap-1"><BadgeCheck className="h-4 w-4 text-forest" aria-hidden="true" />{t("owner")}: {l.ownerId}</span>
          {!isSeedListing(l) && !(Number(l.reviews) > 0)
            ? <span className="inline-flex items-center gap-1 rounded-full bg-leaf/15 px-2 py-0.5 text-[11px] font-extrabold text-forest ring-1 ring-leaf/30 rtl:leading-[2]"><Sparkles className="h-3.5 w-3.5 text-leafink" aria-hidden="true" />{t("ls_new_badge")}</span>
            : <span className="inline-flex items-center gap-1"><Star className="h-4 w-4 fill-gold text-gold" aria-hidden="true" />{Number(l.rating || 0).toFixed(1)}</span>}
        </div>
        <button onClick={() => onBook(l)} disabled={!l.available}
          className="inline-flex items-center justify-center gap-2 rounded-xl bg-forest px-4 py-2.5 text-sm font-bold text-ivory shadow-sm transition-all duration-200 hover:bg-[#0f4a28] hover:shadow-md active:scale-[0.98] disabled:cursor-not-allowed disabled:bg-soil/20 disabled:text-soil/80 focus:outline-none focus-visible:ring-2 focus-visible:ring-gold focus-visible:ring-offset-2">
          <CalendarDays className="h-4 w-4" aria-hidden="true" />{l.available ? t("request") : t("unavailable")}
        </button>
        {l.available && (
          <button type="button" onClick={() => onBook(l, true)} className="-mt-1 inline-flex min-h-[44px] items-center justify-center gap-1.5 rounded-xl px-3 text-sm font-bold text-forest ring-1 ring-forest/25 transition hover:bg-forest/5">
            <HandCoins className="h-4 w-4" aria-hidden="true" />{t("ask_make_offer")}
          </button>
        )}
      </div>
    </article>
  );
}

function Marketplace({ fuel = null, t, dn, lang, listings, onBook, filters, setFilters, activeProvinces, userLoc, setUserLoc, onLive, country = "PK", setCountry, demoMode = false, fallbackProps, toast }) {
  // short skeleton while listings settle (first paint and country switch)
  const [ready, setReady] = useState(false);
  useEffect(() => { setReady(false); const id = setTimeout(() => setReady(true), 420); return () => clearTimeout(id); }, [country]);
  const { category, province = "all", radius, query, nationwide = false } = filters;
  const set = (patch) => setFilters((f) => ({ ...f, ...patch }));
  // Reset filters: category, search, radius, province, the farm location pin AND the country (back to Pakistan · PKR)
  const resetAll = () => {
    if (setCountry && country !== "PK") setCountry("PK");
    setFilters({ category: "all", province: "all", radius: DEFAULT_RADIUS, query: "", nationwide: false });
    if (setUserLoc) setUserLoc(null);
    if (toast) toast(t("reset_done"));
  };
  const results = useMemo(() => {
    const q = query.trim().toLowerCase();
    return listings
      .filter((l) => (category === "all" || l.category === category))
      .filter((l) => (province === "all" || (l.province || "PB") === province))
      .filter((l) => nationwide || l.distance <= radius)
      .filter((l) => !q || [l.name, l.village, l.district, l.ownerId].join(" ").toLowerCase().includes(q))
      .sort((a, b) => (b.available - a.available) || (a.distance || 0) - (b.distance || 0));
  }, [listings, category, province, radius, query, nationwide]);
  // every active listing in the country for this machine type and search, ignoring distance and province
  const nationwideCount = useMemo(() => {
    const q = query.trim().toLowerCase();
    return listings.filter((l) => l.available && (category === "all" || l.category === category) && (!q || [l.name, l.village, l.district, l.ownerId].join(" ").toLowerCase().includes(q))).length;
  }, [listings, category, query]);
  const showNationwide = () => {
    set({ nationwide: true, province: "all" });
    setTimeout(() => { const el = document.getElementById("market"); if (el) el.scrollIntoView({ behavior: "smooth", block: "start" }); }, 60);
  };
  // when nothing is inside the radius, still show the closest machines (with their real distance)
  const nearestBeyond = useMemo(() => (userLoc ? listings.filter((l) => l.available && !l.unknownPlace && (category === "all" || l.category === category) && l.distance > radius).sort((a, b) => a.distance - b.distance).slice(0, 3) : []), [listings, userLoc, category, radius]);
  const pct = ((radius - 1) / (MAX_RADIUS - 1)) * 100;
  // the consultant card shows when no REAL, approved, available machine of this type is within 40 km
  const realInRange = useMemo(() => (userLoc && userLoc.lat ? listings.filter((l) => !isSeedListing(l) && l.available && (l.status || "approved") === "approved" && (category === "all" || l.category === category) && kmToListing(userLoc, l) <= MATCH_RADIUS_KM).length : null), [listings, userLoc, category]);
  const showConsultant = !!(fallbackProps && fallbackProps.onSendLead && !demoMode && (realInRange === null ? results.length === 0 : realInRange === 0));

  return (
    <section id="market" className="mx-auto max-w-6xl px-4 py-8 sm:px-6" aria-labelledby="market-h">
      <div className="mb-5 flex flex-wrap items-end justify-between gap-3">
        <h2 id="market-h" className="font-display text-2xl font-extrabold text-forest">{t("nav_market")}</h2>
        <p className="text-sm font-semibold text-soil/80" aria-live="polite">{results.length === 0 && nearestBeyond.length > 0
          ? t("results_beyond").replace("{n}", nearestBeyond.length).replace("{km}", radius)
          : t(results.length === 1 ? "results_one" : "results").replace("{n}", results.length)}</p>
      </div>
      <div className="grid gap-6 lg:grid-cols-[300px_1fr]">
        <aside className="h-fit rounded-2xl border border-soil/10 bg-white p-4 shadow-sm lg:sticky lg:top-24" aria-label={t("filters")}>
          <p className="mb-4 flex items-center gap-2 font-bold text-forest"><SlidersHorizontal className="h-4 w-4" aria-hidden="true" />{t("filters")}</p>
          <div className="space-y-5">
            {/* phones get this location box right above the results instead */}
            <div className="hidden lg:block">
              {setCountry && <div className="mb-2"><CountrySelect t={t} country={country} setCountry={setCountry} id="country-market" /></div>}
              <LocationField t={t} lang={lang} id="my-loc" label={t("loc_your")} value={userLoc} onChange={setUserLoc} allowClear />
              <p className="mt-1 text-[11px] text-soil/80">{userLoc ? t("loc_dist_note") : t("loc_dist_hint")}</p>
            </div>
            <div className="relative">
              <label htmlFor="q" className="sr-only">{t("f_search")}</label>
              <Search className="pointer-events-none absolute start-3 top-1/2 h-4 w-4 -translate-y-1/2 text-soil/80" aria-hidden="true" />
              <input id="q" value={query} onChange={(e) => set({ query: e.target.value })} placeholder={t("f_search")} className={inputCls + " ps-9"} />
            </div>
            <fieldset>
              <legend className="mb-2 text-sm font-semibold text-soil">{t("f_category")}</legend>
              <div className="grid grid-cols-2 gap-2">
                {["all", ...CATEGORIES.filter((c) => catalogCats(country).includes(c) || listings.some((l) => l.category === c))].map((c) => (
                  <button key={c} type="button" onClick={() => set({ category: c })} aria-pressed={category === c}
                    className={`flex items-center justify-center gap-1.5 rounded-xl px-2 py-2 text-sm font-semibold ring-1 transition ${category === c ? "bg-forest text-ivory ring-forest" : "bg-ivory text-soil ring-soil/15 hover:ring-leaf"}`}>
                    {c !== "all" && <CategoryIcon category={c} className="h-4 w-4" />}{t("cat_" + c)}
                  </button>
                ))}
              </div>
            </fieldset>
            {country === "PK" && <Field label={t("f_province")} htmlFor="province">
              <select id="province" value={province} onChange={(e) => set({ province: e.target.value })} className={inputCls}>
                <option value="all">{t("all_provinces")}</option>
                {(activeProvinces || PROVINCES).map((c) => <option key={c} value={c}>{provName(lang, c)}</option>)}
              </select>
            </Field>}
            <div>
              <div className="mb-1 flex items-center justify-between">
                <label htmlFor="radius" className="text-sm font-semibold text-soil">{t("f_radius")}</label>
                <span className="rounded-lg bg-forest px-2 py-0.5 text-sm font-bold text-ivory">{radius} {t("km")}</span>
              </div>
              <input id="radius" type="range" min="1" max={MAX_RADIUS} step="1" value={radius} onChange={(e) => set({ radius: Number(e.target.value), nationwide: false })}
                className="range w-full" style={{ "--pct": pct + "%" }} aria-valuetext={`${radius} km`} />
              <div className="mt-1 flex justify-between text-[11px] text-soil/80" dir="ltr"><span>1</span><span>15</span><span>40 km</span></div>
              <p className="mt-1 text-xs text-soil/80">{t("radius_note")}</p>
            </div>
            <button type="button" onClick={resetAll}
              className="min-h-[44px] inline-flex w-full items-center justify-center gap-2 rounded-xl border border-soil/15 px-3 py-2 text-sm font-semibold text-soil hover:bg-ivory">
              <RotateCcw className="h-4 w-4" aria-hidden="true" />{t("reset")}
            </button>
          </div>
        </aside>
        <div className="order-first lg:order-none">
          <div className={`mb-4 rounded-2xl p-4 lg:hidden ${userLoc ? "border border-soil/10 bg-white" : "bg-gold/20 ring-2 ring-gold/60"}`}>
            {!userLoc && <p className="flex items-center gap-2 font-display text-base font-extrabold text-forest"><LocateFixed className="h-5 w-5 text-red-700" aria-hidden="true" />{t("loc_ask_t")}</p>}
            {!userLoc && <p className="mb-2 mt-0.5 text-xs text-soil/80">{t("loc_ask_s")}</p>}
            <LocationField t={t} lang={lang} id="my-loc-m" label={userLoc ? t("loc_your") : null} value={userLoc} onChange={setUserLoc} allowClear placeholder={t("loc_ask_ph")} />
          </div>
          <div className="mb-3 flex flex-wrap items-center justify-between gap-2"><FuelPill t={t} fuel={fuel} /><span className="ms-auto"><ModeBadge t={t} demo={demoMode} /></span></div>
          {showConsultant && (
            <div className="mb-4"><ConsultantCard t={t} lang={lang} request={{ category: category === "all" ? "tractor" : category, district: userLoc ? userLoc.district : "", village: userLoc ? userLoc.village : "", loc: userLoc }} onSendLead={fallbackProps.onSendLead} requireAuth={fallbackProps.requireAuth} /></div>
          )}
          {results.length === 0 ? (
            <div className="flex flex-col items-center rounded-2xl border border-dashed border-soil/25 bg-white px-6 py-14 text-center">
              <Search className="h-10 w-10 text-soil/30" aria-hidden="true" />
              <p className="mt-3 max-w-md text-soil/80">{userLoc ? t("loc_far").replace("{km}", radius).replace("{place}", locLabel(userLoc)) : t("no_results")}</p>
              <div className="mt-4 flex w-full flex-col items-stretch justify-center gap-2 sm:w-auto sm:flex-row sm:flex-wrap sm:items-center">
                {!nationwide && nationwideCount > 0 && (
                  <button type="button" onClick={showNationwide} className="min-h-[48px] inline-flex items-center justify-center gap-2 rounded-xl bg-forest px-5 py-2.5 text-sm font-extrabold text-ivory shadow-md ring-2 ring-gold/60 hover:bg-forest/90 rtl:leading-[2]">
                    <Globe className="h-4 w-4" aria-hidden="true" />{t(country === "PK" ? "mk_show_all" : "mk_show_all_any")}
                    <span className="rounded-full bg-ivory/20 px-2 py-0.5 text-xs font-bold" dir="ltr">{nationwideCount}</span>
                  </button>
                )}
                {onLive && <button type="button" onClick={() => onLive()} className="min-h-[48px] inline-flex items-center justify-center gap-1.5 rounded-xl bg-leafink px-5 py-2.5 text-sm font-bold text-white rtl:leading-[2]"><Radar className="h-4 w-4" aria-hidden="true" />{t("cta_live")}</button>}
                <button type="button" onClick={resetAll} className="min-h-[44px] rounded-xl border border-soil/20 px-4 py-2 text-sm font-semibold text-soil hover:bg-ivory">{t("reset")}</button>
              </div>
              {nearestBeyond.length === 0 && country === "PK" && <PopularMachines t={t} onRequest={(c) => onLive(c)} />}
              {nearestBeyond.length === 0 && fallbackProps && !demoMode && (
                <div className="mt-6 w-full text-start">
                  <ZeroSupplyFallback {...fallbackProps} onSendLead={undefined} request={{ category, loc: userLoc, village: userLoc ? locLabel(userLoc) : "", district: userLoc ? userLoc.district : "", province: userLoc ? userLoc.province : "", country: CUR.id, hours: 4 }} pickCategory={category === "all"} onExpand={null} />
                </div>
              )}
              {nearestBeyond.length > 0 && (
                <div className="mt-8 w-full text-start">
                  <p className="mb-3 text-sm font-bold text-forest">{t("loc_nearest_beyond")}</p>
                  <div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-3">
                    {nearestBeyond.map((l) => <ListingCard key={l.id} l={l} t={t} dn={dn} lang={lang} onBook={onBook} />)}
                  </div>
                </div>
              )}
            </div>
          ) : (
            <>
            {nationwide && (
              <div className="mb-3 flex flex-wrap items-center justify-between gap-2 rounded-xl border border-forest/15 bg-forest/5 px-3 py-2">
                <p className="flex items-center gap-1.5 text-sm font-bold text-forest rtl:leading-[2]"><Globe className="h-4 w-4" aria-hidden="true" />{t(country === "PK" ? "mk_showing_all" : "mk_showing_all_any")}</p>
                <button type="button" onClick={() => set({ nationwide: false })} className="min-h-[40px] rounded-lg border border-forest/20 bg-white px-3 py-1.5 text-xs font-bold text-forest hover:bg-ivory rtl:leading-[2]">{t("mk_back_radius").replace("{km}", radius)}</button>
              </div>
            )}
            <div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-3">
              {ready ? results.map((l) => <ListingCard key={l.id} l={l} t={t} dn={dn} lang={lang} onBook={onBook} />) : Array.from({ length: Math.max(3, Math.min(6, results.length)) }).map((_, i) => <SkeletonCard key={i} />)}
            </div>
            </>
          )}
        </div>
      </div>
    </section>
  );
}

/* "Popular machines in Punjab": shown when no live machine matches nearby, so the page is never empty.
   No fixed prices here: each card invites the farmer to name a rate in Apni Boli. */
// ranges come from the same Pakistan catalog as the Apni Boli machine cards, so both always match
const POPULAR_PK = ["tractor", "harvester", "leveler", "thresher"];
function PopularMachines({ t, onRequest }) {
  return (
    <div className="mt-6 w-full text-start">
      <p className="font-display text-lg font-extrabold text-forest">{t("pop_title")}</p>
      <p className="mb-3 text-xs text-soil/80">{t("pop_sub")}</p>
      <div className="grid grid-cols-2 gap-3 lg:grid-cols-4">
        {POPULAR_PK.map((c) => (
          <div key={c} className="flex flex-col overflow-hidden rounded-2xl border border-soil/10 bg-white shadow-sm">
            <div className="relative aspect-[4/3] min-h-[80px]">
              <MachinePhoto category={c} className="absolute inset-0 h-full w-full" alt={t("one_" + c)} width={400} height={300} />
              <span className="absolute start-2 top-2 inline-flex items-center gap-1 rounded-full bg-white/95 px-2 py-0.5 text-[11px] font-bold text-forest shadow"><CategoryIcon category={c} className="h-3.5 w-3.5" />{t("one_" + c)}</span>
            </div>
            <div className="flex flex-1 flex-col gap-2 p-3">
              <p className="flex items-start gap-1.5 text-sm font-extrabold leading-snug text-forest"><Tag className="mt-0.5 h-4 w-4 shrink-0 text-gold" aria-hidden="true" /><span>{t("pop_own_rate")}</span></p>
              <button type="button" onClick={() => onRequest(c)} className="mt-auto inline-flex min-h-[44px] items-center justify-center gap-1.5 rounded-xl bg-forest px-3 py-2 text-sm font-bold text-ivory hover:bg-[#0f4a28]"><Radar className="h-4 w-4" aria-hidden="true" />{t("pop_book")}</button>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
}

/* Compact, dismissible consultant bar: one-tap Call and WhatsApp on every screen */
function ConsultBar({ t }) {
  const [hidden, setHidden] = useState(() => { try { return window.sessionStorage.getItem("agrishare.consultbar") === "hidden"; } catch (e) { return false; } });
  if (hidden) return null;
  const hide = () => { setHidden(true); try { window.sessionStorage.setItem("agrishare.consultbar", "hidden"); } catch (e) { /* private mode */ } };
  return (
    <div role="complementary" aria-label={t("tb_help")}
      className="fixed bottom-[calc(5rem+env(safe-area-inset-bottom))] start-2 z-30 flex max-w-[calc(100%-5.25rem)] items-center gap-1 rounded-full bg-white/95 py-1 pe-1 ps-3 text-xs font-bold text-forest shadow-lg ring-1 ring-forest/15 backdrop-blur lg:bottom-6 lg:start-6">
      <Headphones className="h-4 w-4 shrink-0 text-gold" aria-hidden="true" />
      <span className="hidden truncate min-[400px]:inline">{t("tb_help")}</span>
      <a href={`tel:${CONSULTANT.primary.tel}`} className="inline-flex min-h-[44px] items-center gap-1 rounded-full bg-forest px-3 text-ivory" aria-label={`${t("tb_call")} ${CONSULTANT.primary.label}`}><Phone className="h-4 w-4" aria-hidden="true" />{t("tb_call")}</a>
      <a href={`https://wa.me/${CONSULTANT.primary.wa}?text=${encodeURIComponent(t("tb_wa_msg"))}`} target="_blank" rel="noopener noreferrer" className="inline-flex min-h-[44px] items-center gap-1 rounded-full bg-[#1f8f4e] px-3 text-white" aria-label={`${t("tb_wa")} ${CONSULTANT.primary.label}`}><MessageCircle className="h-4 w-4" aria-hidden="true" />{t("tb_wa")}</a>
      <button type="button" onClick={hide} className="inline-flex h-9 w-9 shrink-0 items-center justify-center rounded-full text-soil/70 hover:bg-soil/5" aria-label={t("tb_hide")}><X className="h-4 w-4" aria-hidden="true" /></button>
    </div>
  );
}

/* ------------------------------------------------------------------ */
/* Booking modal with transparent price calculator                     */
/* ------------------------------------------------------------------ */
function BookingModal({ listing, t, dn, onClose, onSubmit, session, ecoActive = false, promoFor = () => null, startOffer = false }) {
  const [date, setDate] = useState(addDaysISO(1));
  const [hours, setHours] = useState(4); // number, or "" while the farmer is retyping it
  const MAX_HOURS = 500;
  const hrs = Math.min(MAX_HOURS, Math.max(1, parseInt(hours, 10) || 1));
  const [wantOp, setWantOp] = useState(false);
  const [wantTr, setWantTr] = useState(false);
  const [ack, setAck] = useState(false);
  const [payment, setPayment] = useState("easypaisa");
  const [name, setName] = useState(() => (session && session.name) || store.get("agrishare.renter", {}).name || "");
  const [phone, setPhone] = useState(() => (session && session.phone) || store.get("agrishare.renter", {}).phone || "");
  const listedTr = transportFee(listing.distance);
  const minOffer = Math.ceil((listing.rate * MIN_OFFER_RATIO) / 50) * 50;
  const [offerOn, setOfferOn] = useState(!!startOffer);
  const [offerRate, setOfferRate] = useState(listing.rate);
  const [offerTr, setOfferTr] = useState(listedTr);
  const [note, setNote] = useState("");
  const [smallholder, setSmallholder] = useState(false);
  const [partner, setPartner] = useState(CREDIT_PARTNERS[0]);
  const [dueDays, setDueDays] = useState(120);
  const [tried, setTried] = useState(false);
  const dialogRef = useRef(null);

  useEffect(() => {
    const onKey = (e) => { if (e.key === "Escape") onClose(); };
    document.addEventListener("keydown", onKey);
    const prev = document.body.style.overflow;
    document.body.style.overflow = "hidden";
    const first = dialogRef.current && dialogRef.current.querySelector("input,button,select");
    if (first) first.focus();
    return () => { document.removeEventListener("keydown", onKey); document.body.style.overflow = prev; };
  }, [onClose]);

  const terms = offerOn ? { rate: Number(offerRate) || listing.rate, transport: Number(offerTr) >= 0 ? Number(offerTr) : listedTr } : null;
  const commissionRate = ecoCommission(smallholder ? SMALLHOLDER_COMMISSION : COMMISSION, ecoActive);
  const slot = promoFor(listing.ownerUid);
  const q = withPromo(quote(listing, hrs, wantOp, wantTr, terms, commissionRate), slot);
  const listedQ = withPromo(quote(listing, hrs, wantOp, wantTr, null, commissionRate), slot);
  const payLater = payment === "paylater";
  const advance = Math.round(q.total * ADVANCE_SHARE);
  const balance = q.total - advance;
  const dueDate = (() => { const d = new Date(date + "T00:00:00"); d.setDate(d.getDate() + Number(dueDays)); return d.toISOString().slice(0, 10); })();

  const validate = () => {
    const err = {};
    if (!date || date < todayISO()) err.date = t("err_date");
    if (!name.trim()) err.name = t("err_name");
    if (!/^03\d{9}$/.test(phone.replace(/[\s-]/g, ""))) err.phone = t("err_phone");
    if (!ack) err.ack = t("err_ack");
    if (offerOn) {
      const r = Number(offerRate);
      if (!(r >= minOffer && r <= listing.rate)) err.offer = t("bk_offer_min").replace("{min}", pkr(minOffer)).replace("{max}", pkr(listing.rate));
      const tr = Number(offerTr);
      if (listing.transport === "optional" && wantTr && !(tr >= 0 && tr <= listedTr)) err.offerTr = t("bk_offer_min").replace("{min}", pkr(0)).replace("{max}", pkr(listedTr));
    }
    return err;
  };
  const errors = tried ? validate() : {};

  const submit = (e) => {
    e.preventDefault();
    setTried(true);
    if (Object.keys(validate()).length) return;
    store.set("agrishare.renter", { name: name.trim(), phone: phone.trim() });
    onSubmit({ date, hours: q.hours, operator: listing.operator === "optional" ? wantOp : listing.operator === "included", transport: listing.transport === "optional" ? wantTr : listing.transport === "included", payment, renterName: name.trim(), renterPhone: phone.replace(/[\s-]/g, ""), quote: q,
      offer: offerOn ? { rate: q.rate, transport: listing.transport === "optional" && wantTr ? q.transport : null, note: note.trim(), listedTotal: listedQ.total } : null,
      smallholder, financing: payLater ? { partner, advance, balance, dueDate, status: "pending" } : null });
  };

  const Row = ({ label, value, muted, strong }) => (
    <div className={`flex items-center justify-between gap-3 py-1.5 ${strong ? "text-base font-extrabold text-forest" : "text-sm"} ${muted ? "text-soil/80" : "text-soil"}`}>
      <span>{label}</span><span className="tabular-nums" dir="ltr">{value}</span>
    </div>
  );

  return (
    <div className="fixed inset-0 z-50 flex items-end justify-center bg-soil/50 p-0 backdrop-blur-sm sm:items-center sm:p-4" onMouseDown={(e) => { if (e.target === e.currentTarget) onClose(); }}>
      <div ref={dialogRef} role="dialog" aria-modal="true" aria-labelledby="bk-h" className="max-h-[94vh] w-full max-w-3xl overflow-y-auto rounded-t-3xl bg-ivory shadow-2xl sm:rounded-3xl">
        <div className="sticky top-0 z-10 flex items-center gap-3 border-b border-soil/10 bg-ivory/95 px-5 py-4 backdrop-blur">
          <span className="flex h-10 w-10 items-center justify-center rounded-xl bg-forest text-gold"><CategoryIcon category={listing.category} className="h-5 w-5" /></span>
          <div className="min-w-0">
            <h2 id="bk-h" className="font-display text-lg font-extrabold text-forest">{t("bk_title")}</h2>
            <p className="truncate text-sm text-soil/80">{listing.name} · {listing.village}, {dn(listing.district)} · {pkr(listing.rate)}{t("per_hour")}</p>
          </div>
          <button onClick={onClose} className="ms-auto rounded-lg p-2 text-soil hover:bg-soil/5" aria-label={t("close")}><X className="h-5 w-5" /></button>
        </div>
        <form onSubmit={submit} noValidate className="grid gap-5 p-5 md:grid-cols-2 [&>*]:min-w-0">
          <div className="space-y-4">
            <Field label={t("bk_date")} htmlFor="bk-date" error={errors.date}>
              <input id="bk-date" type="date" min={todayISO()} value={date} onChange={(e) => setDate(e.target.value)} className={inputCls} />
            </Field>
            <Field label={t("bk_hours")} htmlFor="bk-hours">
              <div className="flex items-center gap-2">
                <button type="button" onClick={() => setHours(Math.max(1, hrs - 1))} className="rounded-xl border border-soil/20 bg-white p-2.5 text-forest hover:bg-ivory" aria-label="Decrease hours"><Minus className="h-4 w-4" /></button>
                <input id="bk-hours" type="number" inputMode="numeric" min="1" max={MAX_HOURS} value={hours}
                  onChange={(e) => { const v = e.target.value.replace(/[^0-9]/g, ""); setHours(v === "" ? "" : Math.min(MAX_HOURS, parseInt(v, 10) || 0) || ""); }}
                  onBlur={() => setHours(hrs)} className={inputCls + " text-center font-bold"} />
                <button type="button" onClick={() => setHours(Math.min(MAX_HOURS, hrs + 1))} className="rounded-xl border border-soil/20 bg-white p-2.5 text-forest hover:bg-ivory" aria-label="Increase hours"><Plus className="h-4 w-4" /></button>
              </div>
            </Field>
            <Toggle id="bk-op" label={t("bk_operator") + " (+PKR 500/hr)"}
              sub={listing.operator === "included" ? t("op_included") : listing.operator === "none" ? t("op_none") : t("op_optional")}
              checked={listing.operator === "included" ? true : wantOp} disabled={listing.operator !== "optional"} onChange={setWantOp} />
            <Toggle id="bk-tr" label={`${t("bk_transport")} (+${pkr(listedTr)} · ${listing.distance} ${t("km")})`}
              sub={listing.transport === "included" ? t("tr_included") : listing.transport === "self" ? t("tr_self") : t("tr_optional")}
              checked={listing.transport === "included" ? true : wantTr} disabled={listing.transport !== "optional"} onChange={setWantTr} />
            <Toggle id="bk-small" label={t("bk_smallholder")} sub={t("bk_smallholder_sub")} checked={smallholder} onChange={setSmallholder} />
            <div className={`rounded-2xl p-1 ${offerOn ? "bg-gold/20 ring-1 ring-gold/60" : ""}`}>
              <div role="radiogroup" aria-label={t("ask_choice_t")} className="p-1">
                <p className="mb-1.5 text-sm font-bold text-forest rtl:leading-[2]">{t("ask_choice_t")}</p>
                <div className="grid gap-2 sm:grid-cols-2">
                  {[[false, CircleCheck, "ask_choice_accept", `${pkr(listing.rate)}${t("per_hour")}`], [true, HandCoins, "ask_choice_offer", t("ask_choice_offer_s")]].map(([val, I, k, sub]) => (
                    <button key={String(val)} type="button" role="radio" aria-checked={offerOn === val} onClick={() => setOfferOn(val)}
                      className={`flex min-h-[52px] items-start gap-2 rounded-xl p-2.5 text-start ring-1 transition ${offerOn === val ? "bg-forest text-ivory ring-forest" : "bg-white text-forest ring-soil/15 hover:ring-leaf"}`}>
                      <I className="mt-0.5 h-4 w-4 shrink-0" aria-hidden="true" />
                      <span className="min-w-0"><span className="block text-sm font-bold rtl:leading-[2]">{t(k)}</span><span className={`block text-[11px] ${offerOn === val ? "text-ivory/80" : "text-soil/80"}`} dir="auto">{sub}</span></span>
                    </button>
                  ))}
                </div>
              </div>
              {offerOn && (
                <div className="grid gap-3 p-2 pt-3">
                  <Field label={t("bk_offer_rate")} htmlFor="of-rate" error={errors.offer} hint={`${t("bk_listed")}: ${pkr(listing.rate)}${t("per_hour")} · min ${pkr(minOffer)}`}>
                    <MoneyInput id="of-rate" min={minOffer} max={listing.rate} step="50" value={offerRate} onChange={setOfferRate} className={inputCls} />
                  </Field>
                  {listing.transport === "optional" && wantTr && (
                    <Field label={t("bk_offer_tr")} htmlFor="of-tr" error={errors.offerTr} hint={`${t("bk_listed")}: ${pkr(listedTr)}`}>
                      <MoneyInput id="of-tr" min={0} max={listedTr} step="50" value={offerTr} onChange={setOfferTr} className={inputCls} />
                    </Field>
                  )}
                  <Field label={t("bk_offer_note")} htmlFor="of-note">
                    <textarea id="of-note" rows={2} maxLength={240} value={note} onChange={(e) => setNote(e.target.value)} placeholder={t("bk_offer_note_ph")} className={inputCls} />
                  </Field>
                </div>
              )}
            </div>
            <Field label={t("bk_name")} htmlFor="bk-name" error={errors.name}>
              <input id="bk-name" value={name} onChange={(e) => setName(e.target.value)} className={inputCls} autoComplete="name" />
            </Field>
            <Field label={t("bk_phone")} htmlFor="bk-phone" error={errors.phone} hint={t("bk_privacy")}>
              <input id="bk-phone" inputMode="tel" dir="ltr" placeholder="03XX XXXXXXX" value={phone} onChange={(e) => setPhone(e.target.value)} className={inputCls} autoComplete="tel" />
            </Field>
          </div>
          <div className="space-y-4">
            <div className="rounded-2xl bg-white p-4 ring-1 ring-soil/10">
              <p className="mb-2 flex items-center gap-2 text-sm font-bold text-forest"><Calculator className="h-4 w-4" aria-hidden="true" />{t("bk_breakdown")}</p>
              {offerOn && <p className="mb-1 inline-flex items-center gap-1 rounded-full bg-gold/25 px-2 py-0.5 text-[11px] font-bold text-soil"><Tag className="h-3 w-3" aria-hidden="true" />{t("bk_your_offer")}</p>}
              <Row label={`${t("bk_base")} (${pkr(q.rate)} × ${q.hours}h)`} value={pkr(q.base)} />
              <Row label={`${t("bk_op")}${q.operator ? ` (500 × ${q.hours}h)` : ""}`} value={listing.operator === "included" ? t("included_word") : q.operator ? pkr(q.operator) : t("not_added")} muted={!q.operator} />
              <Row label={t("bk_tr")} value={listing.transport === "included" ? t("included_word") : q.transport ? pkr(q.transport) : t("not_added")} muted={!q.transport} />
              <div className="my-1 border-t border-dashed border-soil/20" />
              <Row label={t("bk_sub")} value={pkr(q.subtotal)} />
              <Row label={commLabel(t, q)} value={pkr(q.commission)} />
              <div className="my-1 border-t border-soil/20" />
              <Row label={t("bk_total")} value={pkr(q.total)} strong />
              {offerOn && q.total !== listedQ.total && <p className="text-end text-xs text-soil/80" dir="ltr">{t("bk_listed")}: <s>{pkr(listedQ.total)}</s> · −{pkr(listedQ.total - q.total)}</p>}
              <p className="mt-2 flex items-start gap-2 rounded-lg bg-gold/15 p-2 text-xs font-semibold text-soil"><Fuel className="mt-0.5 h-3.5 w-3.5 shrink-0" aria-hidden="true" />{t("bk_fuel_line")}</p>
            </div>
            <fieldset>
              <legend className="mb-1 text-sm font-semibold text-soil">{t("bk_pay")}</legend>
              <p className="mb-2 text-xs text-soil/80">{t("bk_pay_note")}</p>
              <div className="grid gap-2">
                {[["paylater", t("pay_paylater"), Sprout], ["easypaisa", t("pay_easypaisa"), Wallet], ["jazzcash", t("pay_jazzcash"), Smartphone], ["agent", t("pay_agent"), Users]].map(([v, l, Icon]) => (
                  <label key={v} className={`flex cursor-pointer items-center gap-3 rounded-xl border px-3 py-2.5 text-sm font-semibold ${payment === v ? "border-forest bg-forest/5 text-forest" : "border-soil/15 bg-white text-soil"}`}>
                    <input type="radio" name="payment" value={v} checked={payment === v} onChange={() => setPayment(v)} className="accent-forest" />
                    <Icon className="h-4 w-4 shrink-0" aria-hidden="true" />{l}
                  </label>
                ))}
              </div>
              {payLater && (
                <div className="mt-2 space-y-3 rounded-xl border border-leaf/40 bg-leaf/10 p-3">
                  <div className="grid grid-cols-2 gap-2 text-center">
                    <div className="rounded-lg bg-white p-2 ring-1 ring-soil/10"><p className="text-[11px] font-semibold text-soil/80">{t("pl_now")}</p><p className="font-display text-lg font-extrabold text-forest" dir="ltr">{pkr(advance)}</p></div>
                    <div className="rounded-lg bg-white p-2 ring-1 ring-soil/10"><p className="text-[11px] font-semibold text-soil/80">{t("pl_later")}</p><p className="font-display text-lg font-extrabold text-soil" dir="ltr">{pkr(balance)}</p></div>
                  </div>
                  <fieldset>
                    <legend className="mb-1 text-xs font-bold text-soil">{t("pl_partner")}</legend>
                    <div className="flex flex-wrap gap-1.5">
                      {CREDIT_PARTNERS.map((pt) => (
                        <button type="button" key={pt} onClick={() => setPartner(pt)} aria-pressed={partner === pt}
                          className={`rounded-full px-3 py-1 text-xs font-bold ring-1 ${partner === pt ? "bg-forest text-ivory ring-forest" : "bg-white text-soil ring-soil/20"}`}>{pt}</button>
                      ))}
                    </div>
                  </fieldset>
                  <label className="block text-xs font-bold text-soil" htmlFor="pl-due">{t("pl_due")}
                    <select id="pl-due" value={dueDays} onChange={(e) => setDueDays(e.target.value)} className={inputCls + " mt-1 py-2 text-sm font-normal"}>
                      {[60, 90, 120, 150, 180].map((d) => <option key={d} value={d}>{d} {t("pl_days")}</option>)}
                    </select>
                  </label>
                  <p className="text-xs text-soil" dir="ltr">{t("pl_due_on")}: <b>{fmtDate(dueDate)}</b></p>
                  <p className="flex items-start gap-1.5 text-[11px] leading-snug text-soil/80"><ShieldCheck className="mt-0.5 h-3.5 w-3.5 shrink-0 text-forest" aria-hidden="true" />{t("pl_risk")}</p>
                </div>
              )}
            </fieldset>
            <div>
              <label className={`flex cursor-pointer items-start gap-3 rounded-xl border p-3 text-sm ${errors.ack ? "border-red-400 bg-red-50" : "border-soil/15 bg-white"}`}>
                <input type="checkbox" checked={ack} onChange={(e) => setAck(e.target.checked)} className="mt-0.5 h-4 w-4 shrink-0 accent-forest" />
                <span className="text-soil">{t("bk_ack")}</span>
              </label>
              {errors.ack && <p className="mt-1 text-xs font-medium text-red-700">{errors.ack}</p>}
            </div>
            <div className="flex min-w-0 flex-col-reverse gap-2">
              <button type="button" onClick={onClose} className="min-h-[44px] rounded-xl border border-soil/20 px-4 py-2.5 text-sm font-bold text-soil hover:bg-white">{t("cancel")}</button>
              <button type="submit" className="flex-wrap inline-flex items-center justify-center gap-2 rounded-xl bg-forest px-4 py-3 text-sm font-bold text-ivory hover:bg-[#0f4a28] focus:outline-none focus-visible:ring-2 focus-visible:ring-gold focus-visible:ring-offset-2">
                {offerOn ? <Tag className="h-4 w-4" aria-hidden="true" /> : <Send className="h-4 w-4" aria-hidden="true" />}{offerOn ? t("bk_send_offer") : t("bk_submit")} · <span dir="ltr">{payLater ? `${pkr(advance)} ${t("pl_now_short")}` : pkr(q.total)}</span>
              </button>
            </div>
          </div>
        </form>
      </div>
    </div>
  );
}

/* ------------------------------------------------------------------ */
/* My Bookings                                                         */
/* ------------------------------------------------------------------ */
function StatusTracker({ status, t }) {
  const idx = status === "countered" ? 0 : STATUS_FLOW.indexOf(status);
  const stopped = status === "declined" || status === "cancelled";
  return (
    <ol className="grid grid-cols-4 gap-1" aria-label="Booking status">
      {STATUS_FLOW.map((s, i) => {
        const done = !stopped && i <= idx;
        const current = !stopped && i === idx;
        return (
          <li key={s} className="flex flex-col items-center text-center">
            <div className="flex w-full items-center">
              <span className={`h-1 flex-1 rounded ${i === 0 ? "invisible" : done ? "bg-leaf" : "bg-soil/15"}`} />
              <span className={`flex h-7 w-7 shrink-0 items-center justify-center rounded-full text-xs font-bold ${done ? "bg-leafink text-white" : "bg-soil/10 text-soil/80"} ${current ? "ring-4 ring-leaf/25" : ""}`}>
                {done ? <Check className="h-4 w-4" aria-hidden="true" /> : i + 1}
              </span>
              <span className={`h-1 flex-1 rounded ${i === STATUS_FLOW.length - 1 ? "invisible" : !stopped && i < idx ? "bg-leaf" : "bg-soil/15"}`} />
            </div>
            <span className={`mt-1 text-[11px] font-semibold leading-tight ${done ? "text-forest" : "text-soil/80"}`}>{t("st_" + s)}</span>
          </li>
        );
      })}
    </ol>
  );
}

function FeedbackForm({ t, onSubmit }) {
  const [rating, setRating] = useState(0);
  const [comment, setComment] = useState("");
  return (
    <form onSubmit={(e) => { e.preventDefault(); if (rating) onSubmit(rating, comment.trim()); }} className="mt-3 space-y-2 rounded-xl bg-ivory p-3">
      <p className="text-sm font-semibold text-soil">{t("mb_rate")}</p>
      <div className="flex gap-1" role="radiogroup" aria-label={t("mb_rate")}>
        {[1, 2, 3, 4, 5].map((n) => (
          <button type="button" key={n} onClick={() => setRating(n)} role="radio" aria-checked={rating === n} aria-label={`${n} star`} className="rounded p-0.5">
            <Star className={`h-7 w-7 ${n <= rating ? "fill-gold text-gold" : "text-soil/30"}`} />
          </button>
        ))}
      </div>
      <label className="sr-only" htmlFor="fb-c">{t("mb_comment")}</label>
      <textarea id="fb-c" rows={2} value={comment} onChange={(e) => setComment(e.target.value)} placeholder={t("mb_comment")} className={inputCls} />
      <button type="submit" disabled={!rating} className="min-h-[44px] rounded-xl bg-forest px-4 py-2 text-sm font-bold text-ivory disabled:opacity-40">{t("mb_feedback")}</button>
    </form>
  );
}

function CounterOfferBox({ b, t, updateBooking }) {
  const c = b.counter;
  const snap = b.listingSnap || { rate: b.quote.listedRate || b.quote.rate, operator: "included", transport: "optional", distance: 0 };
  const nq = withPromo(quote(snap, b.quote.hours, b.operator, b.transport && b.quote.transport > 0, { rate: c.rate, transport: c.transport }, b.smallholder ? SMALLHOLDER_COMMISSION : COMMISSION), b.quote.promo || null);
  return (
    <div className="mt-3 rounded-xl border border-gold/60 bg-gold/10 p-3">
      <p className="flex items-center gap-2 text-sm font-bold text-soil"><Repeat className="h-4 w-4" aria-hidden="true" />{t("mb_counter")}</p>
      <p className="mt-1 text-sm text-soil" dir="ltr">{pkr(c.rate)}/hr{nq.transport ? ` · Transport ${pkr(nq.transport)}` : ""} · <b>Total {pkr(nq.total)}</b></p>
      <div className="mt-2 flex flex-wrap gap-2">
        <button onClick={() => updateBooking(b.id, "confirmed", { quote: nq, agreed: { rate: c.rate, transport: c.transport }, financing: b.financing ? { ...b.financing, advance: Math.round(nq.total * ADVANCE_SHARE), balance: nq.total - Math.round(nq.total * ADVANCE_SHARE) } : null })} className="inline-flex items-center gap-1.5 rounded-lg bg-forest px-3 py-2 text-sm font-bold text-ivory"><Check className="h-4 w-4" aria-hidden="true" />{t("mb_accept_counter")}</button>
        <button onClick={() => updateBooking(b.id, "cancelled")} className="rounded-lg border border-soil/20 px-3 py-2 text-sm font-bold text-soil">{t("mb_decline_counter")}</button>
      </div>
    </div>
  );
}

function MyBookings({ t, dn, bookings, updateBooking, setTab, session, openAuth, onVoucher, requests = [] }) {
  if (!session) {
    return (
      <section className="mx-auto max-w-5xl px-4 py-8 sm:px-6">
        <h2 className="mb-5 font-display text-2xl font-extrabold text-forest">{t("mb_title")}</h2>
        <div className="relative mb-4 rounded-2xl border border-soil/10 bg-white p-4 shadow-sm" aria-label={t("mb_sample_t")}>
          <span className="absolute end-3 top-3 rounded-full bg-gold/30 px-2 py-0.5 text-[10px] font-extrabold uppercase tracking-wide text-soil">{t("mb_sample_badge")}</span>
          <p className="pe-16 text-xs font-bold uppercase tracking-wide text-soil/80">{t("mb_sample_t")}</p>
          <div className="mt-3 flex gap-3">
            <MachinePhoto category="tractor" name="Massey Ferguson 385" className="h-16 w-20 shrink-0 rounded-xl" alt="" width={160} height={128} />
            <div className="min-w-0">
              <p className="font-bold text-forest" dir="ltr">Massey Ferguson 385</p>
              <p className="text-xs text-soil/80" dir="ltr">AS-SAMPLE · {fmtDate(addDaysISO(2))} · 6h · {pkr(15900)}</p>
              <span className="mt-1 inline-block rounded-full bg-leaf/15 px-2 py-0.5 text-[11px] font-bold text-forest">{t("st_confirmed")}</span>
            </div>
          </div>
          <div className="mt-3"><StatusTracker status="confirmed" t={t} /></div>
          <p className="mt-2 text-xs text-soil/80">{t("mb_sample_s")}</p>
        </div>
        <div className="flex flex-col items-center rounded-2xl border border-dashed border-soil/25 bg-white px-6 py-10 text-center">
          <LogIn className="h-10 w-10 text-soil/30" aria-hidden="true" />
          <p className="mt-3 text-soil/80">{t("mb_signin")}</p>
          <div className="mt-4 flex gap-2">
            <button onClick={() => openAuth("signin")} className="min-h-[44px] rounded-xl bg-forest px-4 py-2 text-sm font-bold text-ivory">{t("auth_signin")}</button>
            <button onClick={() => openAuth("signup")} className="min-h-[44px] rounded-xl border border-forest/30 px-4 py-2 text-sm font-bold text-forest">{t("auth_signup")}</button>
          </div>
        </div>
      </section>
    );
  }
  const mine = bookings.filter((b) => b.channel === "ussd" || b.own);
  const sorted = [...mine].sort((a, b) => b.createdAt - a.createdAt);
  return (
    <section className="mx-auto max-w-5xl px-4 py-8 sm:px-6" aria-labelledby="mb-h">
      <h2 id="mb-h" className="mb-5 font-display text-2xl font-extrabold text-forest">{t("mb_title")}</h2>
      {requests.length > 0 && (
        <div className="mb-6 rounded-2xl border border-gold/50 bg-gold/10 p-4" aria-labelledby="mb-open-h">
          <h3 id="mb-open-h" className="mb-3 flex items-center gap-2 font-bold text-forest"><Radar className="h-4 w-4 text-gold" aria-hidden="true" />{t("mb_open_requests")} <span className="rounded-full bg-gold px-1.5 text-[11px] text-soil">{requests.length}</span></h3>
          <ul className="grid gap-2 sm:grid-cols-2">
            {requests.map((r) => (
              <li key={r.id} className="flex flex-wrap items-center gap-x-3 gap-y-2 rounded-xl bg-white p-3 text-sm ring-1 ring-soil/10">
                <CategoryIcon category={r.category} className="h-5 w-5 shrink-0 text-forest" />
                <span className="min-w-0 flex-1 basis-40">
                  <span className="block break-words font-bold text-forest">{t("one_" + r.category)}{r.village ? ` · ${r.village}` : ""}</span>
                  <span className="block text-xs text-soil/80" dir="ltr">{r.id} · {pkr(r.rate)}/hr · {r.hours}h · {fmtDate(r.date)} · T{r.tierReached || 1}</span>
                </span>
                <button type="button" onClick={() => setTab("live-request")} className="ms-auto shrink-0 rounded-lg bg-forest px-3 py-1.5 text-xs font-bold text-ivory">{t("mb_open_view")}</button>
              </li>
            ))}
          </ul>
        </div>
      )}
      {sorted.length === 0 ? (
        <div className="flex flex-col items-center rounded-2xl border border-dashed border-soil/25 bg-white px-6 py-14 text-center">
          <ClipboardList className="h-10 w-10 text-soil/30" aria-hidden="true" />
          <p className="mt-3 text-soil/80">{t("mb_empty")}</p>
          <button onClick={() => setTab("marketplace")} className="mt-4 inline-flex items-center gap-2 rounded-xl bg-forest px-4 py-2 text-sm font-bold text-ivory"><Store className="h-4 w-4" aria-hidden="true" />{t("nav_market")}</button>
        </div>
      ) : (
        <div className="space-y-4">
          {sorted.map((b) => (
            <article key={b.id} className="rounded-2xl border border-soil/10 bg-white p-4 shadow-sm sm:p-5">
              <div className="flex flex-wrap items-start gap-3">
                <span className="flex h-11 w-11 shrink-0 items-center justify-center rounded-xl bg-forest text-gold"><CategoryIcon category={b.category} className="h-6 w-6" /></span>
                <div className="min-w-0 flex-1">
                  <div className="flex flex-wrap items-center gap-2">
                    <h3 className="font-display font-extrabold text-forest">{b.listingName}</h3>
                    <StatusPill status={b.status} t={t} />
                  </div>
                  <p className="mt-0.5 text-sm text-soil/80">
                    <span dir="ltr" className="font-mono font-semibold">{b.id}</span> · {fmtDate(b.date)} · {b.quote.hours}h · {dn(b.district)} · {b.channel === "ussd" ? t("mb_via_ussd") : b.channel === "live" ? t("mb_via_live") : t("mb_via_app")}
                  </p>
                </div>
                <div className="text-end">
                  <p className="text-xs text-soil/80">{t("bk_total")}</p>
                  <p className="font-display text-xl font-extrabold text-forest" dir="ltr">{pkr(b.quote.total)}</p>
                </div>
              </div>
              <div className="mt-4"><StatusTracker status={b.status} t={t} /></div>
              {onVoucher && <button onClick={() => onVoucher(b.id)} className="mt-3 inline-flex items-center gap-1.5 rounded-xl bg-forest/5 px-3 py-1.5 text-xs font-bold text-forest ring-1 ring-forest/15 transition hover:bg-forest/10"><Ticket className="h-4 w-4" aria-hidden="true" />{t("act_view_voucher")} <span className="font-mono" dir="ltr">{voucherCode(b)}</span></button>}
              <div className="mt-3 grid gap-x-6 gap-y-1 rounded-xl bg-ivory p-3 text-xs text-soil sm:grid-cols-2">
                <span>{t("bk_base")}: <b dir="ltr">{pkr(b.quote.base)}</b></span>
                <span>{t("bk_op")}: <b>{b.quote.operator ? pkr(b.quote.operator) : b.operator ? t("included_word") : t("not_added")}</b></span>
                <span>{t("bk_tr")}: <b>{b.quote.transport ? pkr(b.quote.transport) : b.transport ? t("included_word") : t("not_added")}</b></span>
                <span>{commLabel(t, b.quote)}: <b dir="ltr">{pkr(b.quote.commission)}</b></span>
                <span>{t("bk_pay")}: <b>{t("pay_" + b.payment)}</b></span>
                <span>{t("owner")}: <b dir="ltr">{b.ownerId}</b></span>
              </div>
              {b.offer && (
                <p className="mt-3 flex flex-wrap items-center gap-2 text-xs text-soil">
                  <span className="inline-flex items-center gap-1 rounded-full bg-gold/25 px-2 py-0.5 font-bold"><Tag className="h-3 w-3" aria-hidden="true" />{t("offer_badge")}</span>
                  <span dir="ltr">{t("mb_offer_line").replace("{rate}", pkr(b.offer.rate))} · {t("bk_listed")} {pkr(b.quote.listedRate)}/hr</span>
                  {b.offer.note && <span className="italic text-soil/80">"{b.offer.note}"</span>}
                </p>
              )}
              {b.financing && !["cancelled", "declined"].includes(b.status) && (
                <div className={`mt-3 rounded-xl p-3 text-sm ring-1 ${b.financing.status === "settled" ? "bg-leaf/10 ring-leaf/40" : "bg-gold/10 ring-gold/50"}`}>
                  <p className="flex flex-wrap items-center gap-2 font-bold text-soil"><Sprout className="h-4 w-4 text-forest" aria-hidden="true" />{t("pay_paylater")} · {b.financing.partner}
                    <span className={`rounded-full px-2 py-0.5 text-[11px] ${b.financing.status === "settled" ? "bg-forest text-ivory" : "bg-gold text-soil"}`}>{b.financing.status === "settled" ? t("pl_settled") : t("pl_pending")}</span>
                  </p>
                  <p className="mt-1 text-xs text-soil" dir="ltr">{t("pl_now")}: <b>{pkr(b.financing.advance)}</b> · {t("pl_later")}: <b>{pkr(b.financing.balance)}</b> · {t("pl_due_on")} {fmtDate(b.financing.dueDate)}</p>
                  {b.financing.status === "settled" && b.financing.settledBy && <p className="mt-1 text-xs text-forest">{t("pl_settled_by").replace("{id}", b.financing.settledBy)}</p>}
                  {b.financing.status !== "settled" && <button onClick={() => setTab("agri-mandi")} className="mt-2 inline-flex items-center gap-1.5 rounded-lg bg-forest px-3 py-1.5 text-xs font-bold text-ivory"><Wheat className="h-3.5 w-3.5" aria-hidden="true" />{t("pl_settle_mandi")}</button>}
                </div>
              )}
              {b.status === "countered" && b.counter && <CounterOfferBox b={b} t={t} updateBooking={updateBooking} />}
              {b.status === "sent" && (
                <div className="mt-3 flex flex-wrap items-center gap-2">
                  <p className="flex flex-1 items-center gap-2 text-sm text-soil/80"><Hourglass className="h-4 w-4 text-gold" aria-hidden="true" />{t("mb_waiting")}</p>
                  {session && b.ownerUid && b.ownerUid === session.uid && <button onClick={() => setTab("owner-portal")} className="min-h-[44px] rounded-xl bg-forest/5 px-3 py-2 text-sm font-bold text-forest hover:bg-forest/10">{t("mb_go_owner")}</button>}
                  <button onClick={() => updateBooking(b.id, "cancelled")} className="rounded-xl border border-soil/20 px-3 py-2 text-sm font-bold text-soil hover:bg-ivory">{t("mb_cancel")}</button>
                </div>
              )}
              {b.status === "confirmed" && (
                <button onClick={() => updateBooking(b.id, "completed")} className="mt-3 inline-flex items-center gap-2 rounded-xl bg-forest px-4 py-2 text-sm font-bold text-ivory hover:bg-[#0f4a28]">
                  <CircleCheck className="h-4 w-4" aria-hidden="true" />{t("mb_complete")}
                </button>
              )}
              {["confirmed", "completed", "feedback"].includes(b.status) && <ProofStrip t={t} deal={bookingDeal(b)} className="mt-3" />}
              {b.status === "completed" && <FeedbackForm t={t} onSubmit={(rating, comment) => updateBooking(b.id, "feedback", { rating, comment })} />}
              {b.status === "feedback" && (
                <p className="mt-3 flex items-center gap-2 text-sm text-forest">
                  <span className="flex">{[1, 2, 3, 4, 5].map((n) => <Star key={n} className={`h-4 w-4 ${n <= (b.rating || 0) ? "fill-gold text-gold" : "text-soil/25"}`} aria-hidden="true" />)}</span>
                  {t("mb_thanks")}{b.comment ? ` "${b.comment}"` : ""}
                </p>
              )}
            </article>
          ))}
        </div>
      )}
    </section>
  );
}

