// Reply language: follows the selected app language; in English mode it follows what the farmer typed
function pickReplyLang(raw, uiLang) {
  // Mirror the message: English in -> English out, Roman Urdu in -> Roman Urdu out,
  // Perso-Arabic script in -> that script (the selected regional language when it fits).
  const typed = detectReplyLang(raw); // en | ur | ro
  return typed === "ur" ? scriptLang(String(raw || ""), uiLang) : typed;
}

